_OPENSSL_BIN: str | None = None

AWSCLI_COMMAND_TIMEOUT_SEC = 300.0
AWSCLI_DISCOVERY_TIMEOUT_SEC = 30.0
AWSCLI_SKELETON_TIMEOUT_SEC = 60.0
AWSCLI_VERSION_TIMEOUT_SEC = 10.0


def openssl_bin() -> str:
    global _OPENSSL_BIN
    if _OPENSSL_BIN:
        return _OPENSSL_BIN
    path = shutil.which("openssl")
    if not path:
        raise RuntimeError("openssl is required for AWS SigV4 signing")
    _OPENSSL_BIN = path
    return path


def sigv4_sha256_digest(data: bytes) -> bytes:
    # AWS SigV4 requires SHA-256 for payload and canonical request hashing.
    proc = subprocess.run(
        [openssl_bin(), "dgst", "-sha256", "-binary"],
        input=data,
        capture_output=True,
        check=False,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"openssl sha256 failed: {proc.stderr.decode('utf-8', 'replace').strip()}")
    return proc.stdout


def sigv4_sha256_hexdigest(data: bytes) -> str:
    return sigv4_sha256_digest(data).hex()


def sigv4_hmac_sha256_digest(key: bytes, msg: str) -> bytes:
    # AWS SigV4 key derivation is defined in terms of HMAC-SHA256.
    proc = subprocess.run(
        [
            openssl_bin(),
            "dgst",
            "-sha256",
            "-mac",
            "HMAC",
            "-macopt",
            f"hexkey:{key.hex()}",
            "-binary",
        ],
        input=msg.encode("utf-8"),
        capture_output=True,
        check=False,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"openssl hmac-sha256 failed: {proc.stderr.decode('utf-8', 'replace').strip()}")
    return proc.stdout


def sigv4_hmac_sha256_hexdigest(key: bytes, data: str) -> str:
    return sigv4_hmac_sha256_digest(key, data).hex()


def sigv4_sign(
    method: str,
    url: str,
    body: bytes,
    service: str,
    region: str,
    access_key: str,
    secret_key: str,
    session_token: str,
    extra_headers: dict[str, str] | None = None,
) -> dict[str, str]:
    if not access_key or not secret_key:
        return {}
    parsed = urlparse.urlparse(url)
    host = parsed.netloc
    canonical_uri = parsed.path or "/"
    canonical_query = parsed.query or ""

    now = datetime.datetime.now(datetime.timezone.utc)
    amz_date = now.strftime("%Y%m%dT%H%M%SZ")
    date_stamp = now.strftime("%Y%m%d")
    payload_hash = sigv4_sha256_hexdigest(body)

    headers: dict[str, str] = {
        "host": host,
        "x-amz-date": amz_date,
        "x-amz-content-sha256": payload_hash,
    }
    if session_token:
        headers["x-amz-security-token"] = session_token
    if extra_headers:
        for key, value in extra_headers.items():
            headers[key.lower()] = value

    sorted_header_keys = sorted(headers.keys())
    canonical_headers = "".join(f"{key}:{headers[key].strip()}\n" for key in sorted_header_keys)
    signed_headers = ";".join(sorted_header_keys)

    canonical_request = "\n".join(
        [
            method,
            canonical_uri,
            canonical_query,
            canonical_headers,
            signed_headers,
            payload_hash,
        ]
    )

    credential_scope = f"{date_stamp}/{region}/{service}/aws4_request"
    string_to_sign = "\n".join(
        [
            "AWS4-HMAC-SHA256",
            amz_date,
            credential_scope,
            sigv4_sha256_hexdigest(canonical_request.encode("utf-8")),
        ]
    )
    k_date = sigv4_hmac_sha256_digest(("AWS4" + secret_key).encode("utf-8"), date_stamp)
    k_region = sigv4_hmac_sha256_digest(k_date, region)
    k_service = sigv4_hmac_sha256_digest(k_region, service)
    k_signing = sigv4_hmac_sha256_digest(k_service, "aws4_request")
    signature = sigv4_hmac_sha256_hexdigest(k_signing, string_to_sign)

    authorization = (
        "AWS4-HMAC-SHA256 "
        f"Credential={access_key}/{credential_scope}, "
        f"SignedHeaders={signed_headers}, "
        f"Signature={signature}"
    )

    signed: dict[str, str] = {
        "Authorization": authorization,
        "X-Amz-Date": amz_date,
        "X-Amz-Content-Sha256": payload_hash,
        "Host": host,
    }
    if session_token:
        signed["X-Amz-Security-Token"] = session_token
    if extra_headers:
        signed.update(extra_headers)
    return signed


def incidentmanager_is_contact_operation(operation: str) -> bool:
    return operation in INCIDENTMANAGER_CONTACT_OPERATIONS


def incidentmanager_raw_fallback_route(operation: str) -> tuple[str, str]:
    if incidentmanager_is_contact_operation(operation):
        return ("POST", "/")
    if not operation:
        return ("POST", "/")
    return ("POST", f"/{operation[0].lower()}{operation[1:]}")


def singlesignonoidc_raw_fallback_route(operation: str) -> tuple[str, str]:
    if operation == "RegisterClient":
        return ("POST", "/client/register")
    if operation == "StartDeviceAuthorization":
        return ("POST", "/device_authorization")
    if operation == "CreateTokenWithIAM":
        return ("POST", "/token?aws_iam=t")
    if operation == "CreateToken":
        return ("POST", "/token")
    return ("POST", "/token")


def singlesignonportal_raw_fallback_route(operation: str) -> tuple[str, str]:
    if operation == "ListAccounts":
        return ("GET", "/assignment/accounts")
    if operation == "ListAccountRoles":
        return ("GET", "/assignment/roles?account_id={accountId}")
    if operation == "GetRoleCredentials":
        return ("GET", "/federation/credentials?account_id={accountId}&role_name={roleName}")
    if operation == "Logout":
        return ("POST", "/logout")
    return ("GET", "/assignment/accounts")


_CONTROLTOWER_RAW_FALLBACK_ROUTES: dict[str, tuple[str, str]] | None = None
_INSPECTORV2_RAW_FALLBACK_ROUTES: dict[str, tuple[str, str]] | None = None


def controltower_raw_fallback_routes() -> dict[str, tuple[str, str]]:
    global _CONTROLTOWER_RAW_FALLBACK_ROUTES
    if _CONTROLTOWER_RAW_FALLBACK_ROUTES is not None:
        return _CONTROLTOWER_RAW_FALLBACK_ROUTES

    routes: dict[str, tuple[str, str]] = {}
    cfg = SERVICE_CONFIG.get("controltower", {})
    ops_file = cfg.get("ops_file")
    path = Path(ops_file) if isinstance(ops_file, Path) else None
    if path and path.exists():
        text = path.read_text(encoding="utf-8", errors="replace")
        for match in re.finditer(
            r'\{Name:\s*"([^"]+)",\s*Method:\s*"([^"]+)",\s*URI:\s*"([^"]+)"\}',
            text,
        ):
            op = match.group(1).strip()
            method = match.group(2).strip().upper() or "POST"
            uri = match.group(3).strip() or "/"
            routes[op] = (method, uri)

    _CONTROLTOWER_RAW_FALLBACK_ROUTES = routes
    return routes


