def classify_raw_http_failure(status_code: int, response_text: str) -> tuple[str, str]:
    status, detail = classify_failure(response_text)
    if status != "unknown_error":
        return status, detail
    if status_code == 501:
        return "not_implemented", "http_501"
    try:
        payload = json.loads(response_text)
    except Exception:  # noqa: BLE001
        payload = None
    if isinstance(payload, dict):
        code = payload.get("__type")
        if isinstance(code, str) and code.strip():
            if "NotImplemented" in code:
                return "not_implemented", code
            return "service_error", code
    code_match = re.search(r"<Code>([^<]+)</Code>", response_text)
    if code_match:
        code = code_match.group(1).strip()
        if "NotImplemented" in code:
            return "not_implemented", code
        return "service_error", code
    if status_code >= 400:
        return "service_error", f"http_{status_code}"
    return "unknown_error", detail


def extract_not_implemented_marker(text: str) -> str | None:
    content = text.strip()
    if not content:
        return None

    def _find_not_implemented(value: object) -> str | None:
        if isinstance(value, dict):
            for key, inner in value.items():
                if isinstance(key, str) and re.search(r"not[\s_-]*implemented", key, re.IGNORECASE):
                    return key
                marker = _find_not_implemented(inner)
                if marker:
                    return marker
            return None
        if isinstance(value, list):
            for inner in value:
                marker = _find_not_implemented(inner)
                if marker:
                    return marker
            return None
        if isinstance(value, str):
            for marker in NOT_IMPLEMENTED_MARKERS:
                if marker.lower() in value.lower():
                    return marker
            if re.search(r"\bnot[\s_-]*implemented(?:exception)?\b", value, re.IGNORECASE):
                return value
        return None

    for marker in NOT_IMPLEMENTED_MARKERS:
        if marker.lower() in content.lower():
            return marker

    if re.search(r"\bnot[\s_-]*implemented(?:exception)?\b", content, re.IGNORECASE):
        return "NotImplemented"

    try:
        payload = json.loads(content)
    except Exception:  # noqa: BLE001
        payload = None
    marker = _find_not_implemented(payload)
    if marker:
        return marker

    code_match = re.search(r"<Code>([^<]+)</Code>", content)
    if code_match:
        code = code_match.group(1).strip()
        if re.search(r"NotImplemented", code, re.IGNORECASE):
            return code

    return None


def invoke_raw_endpoint(
    endpoint: Endpoint,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    payload: dict[str, object],
) -> tuple[int, str]:
    route = raw_fallback_route(endpoint)
    if route is None:
        return 0, "raw_route_unavailable"
    method, path_template = route
    payload_for_transport = copy.deepcopy(payload) if isinstance(payload, dict) else {}
    query_params: list[tuple[str, str]] = []
    path = path_template
    neptune_graph_identifier_header = ""
    if endpoint.service == "neptuneanalytics" and isinstance(payload, dict):
        graph_identifier_key = find_key_case_insensitive(payload, "graphIdentifier")
        if graph_identifier_key is not None:
            graph_identifier_value = payload.get(graph_identifier_key)
            if graph_identifier_value is not None:
                neptune_graph_identifier_header = str(graph_identifier_value).strip()

    for placeholder_token in re.findall(r"{([^}]+)}", path_template):
        placeholder = placeholder_token[:-1] if placeholder_token.endswith("+") else placeholder_token
        existing_key = find_key_case_insensitive(payload_for_transport, placeholder)
        if existing_key is None and placeholder != placeholder_token:
            existing_key = find_key_case_insensitive(payload_for_transport, placeholder_token)
        value = ""
        if existing_key is not None:
            raw_value = payload_for_transport.pop(existing_key)
            if raw_value is not None:
                value = str(raw_value).strip()
        if not value and endpoint.service == "lambda":
            if placeholder == "FunctionName":
                value = str(lambda_runtime_state(region).get("function_name", LAMBDA_DEFAULT_FUNCTION_NAME))
            elif placeholder == "CapacityProviderName":
                value = str(lambda_runtime_state(region).get("capacity_provider_name", LAMBDA_DEFAULT_CAPACITY_PROVIDER_NAME))
            elif placeholder == "DurableExecutionArn":
                value = str(lambda_runtime_state(region).get("durable_execution_arn", LAMBDA_DEFAULT_DURABLE_EXECUTION_ARN))
            elif placeholder == "CallbackId":
                value = str(lambda_runtime_state(region).get("callback_id", LAMBDA_DEFAULT_CALLBACK_ID))
        if not value and endpoint.service == "sesv2":
            sesv2_state = sesv2_runtime_state(region)
            if placeholder == "ConfigurationSetName":
                value = str(sesv2_state.get("configuration_set_name") or SESV2_DEFAULT_CONFIGURATION_SET_NAME)
            elif placeholder == "EventDestinationName":
                value = str(sesv2_state.get("event_destination_name") or SESV2_DEFAULT_EVENT_DESTINATION_NAME)
            elif placeholder == "ContactListName":
                value = str(sesv2_state.get("contact_list_name") or SESV2_DEFAULT_CONTACT_LIST_NAME)
            elif placeholder == "EmailAddress":
                value = str(sesv2_state.get("recipient_email") or SESV2_DEFAULT_RECIPIENT_EMAIL)
            elif placeholder == "EmailIdentity":
                value = str(sesv2_state.get("email_identity") or SESV2_DEFAULT_EMAIL_IDENTITY)
            elif placeholder == "PolicyName":
                value = str(sesv2_state.get("policy_name") or SESV2_DEFAULT_POLICY_NAME)
            elif placeholder == "TemplateName":
                value = str(sesv2_state.get("template_name") or SESV2_DEFAULT_TEMPLATE_NAME)
            elif placeholder == "ReputationEntityType":
                value = str(sesv2_state.get("reputation_entity_type") or SESV2_DEFAULT_REPUTATION_ENTITY_TYPE)
            elif placeholder == "ReputationEntityReference":
                value = str(sesv2_state.get("reputation_entity_reference") or SESV2_DEFAULT_REPUTATION_ENTITY_REFERENCE)
        if not value and endpoint.service == "iottwinmaker":
            if placeholder == "workspaceId":
                value = "stackyard-workspace"
            elif placeholder == "componentTypeId":
                value = "com.stackyard.Component"
            elif placeholder == "entityId":
                value = "stackyard-entity"
            elif placeholder == "sceneId":
                value = "stackyard-scene"
            elif placeholder == "syncSource":
                value = "SITEWISE"
            elif placeholder == "metadataTransferJobId":
                value = "mtj-000001"
        if not value and endpoint.service == "iotsitewise":
            if placeholder == "accessPolicyId":
                value = "stackyard-access-policy"
            elif placeholder == "assetId":
                value = "stackyard-asset"
            elif placeholder == "assetModelId":
                value = "stackyard-asset-model"
            elif placeholder == "assetModelCompositeModelId":
                value = "stackyard-composite-model"
            elif placeholder == "interfaceAssetModelId":
                value = "stackyard-interface-asset-model"
            elif placeholder == "assetCompositeModelId":
                value = "stackyard-asset-composite-model"
            elif placeholder == "propertyId":
                value = "stackyard-property"
            elif placeholder == "projectId":
                value = "stackyard-project"
            elif placeholder == "portalId":
                value = "stackyard-portal"
            elif placeholder == "dashboardId":
                value = "stackyard-dashboard"
            elif placeholder == "datasetId":
                value = "stackyard-dataset"
            elif placeholder == "gatewayId":
                value = "stackyard-gateway"
            elif placeholder == "jobId":
                value = "stackyard-job"
            elif placeholder == "computationModelId":
                value = "stackyard-computation-model"
            elif placeholder == "actionId":
                value = "stackyard-action"
            elif placeholder == "executionId":
                value = "stackyard-execution"
            elif placeholder == "capabilityNamespace":
                value = "iotsitewise:opcuacollector:3"
        if not value and endpoint.service == "omics":
            if placeholder in {"sequenceStoreId", "id"}:
                value = "stackyard-sequence-store"
            elif placeholder == "referenceStoreId":
                value = "stackyard-reference-store"
            elif placeholder == "variantStoreId":
                value = "stackyard-variant-store"
            elif placeholder in {"workflowId", "workflowOwnerId"}:
                value = "stackyard-workflow"
            elif placeholder == "runGroupId":
                value = "stackyard-run-group"
            elif placeholder == "runId":
                value = "stackyard-run"
            elif placeholder == "taskId":
                value = "stackyard-task"
            elif placeholder == "jobId":
                value = "stackyard-job"
            elif placeholder == "shareId":
                value = "stackyard-share"
            elif placeholder == "name":
                value = "stackyard-name"
            elif placeholder == "s3AccessPointArn":
                value = "arn:aws:s3:us-east-1:123456789012:accesspoint/stackyard-omics"
            elif placeholder == "resourceArn":
                value = "arn:aws:omics:us-east-1:123456789012:resource/stackyard"
