def parse_csv_args(values: Sequence[str] | None) -> list[str]:
    out: list[str] = []
    for raw in values or []:
        for part in raw.split(","):
            item = part.strip()
            if item:
                out.append(item)
    return out


def normalize_service_name(name: str) -> str:
    key = name.strip().lower()
    key = key.replace("_", "")
    key = key.replace(" ", "")
    return SERVICE_ALIASES.get(key, key)


def remove_backspace_formatting(text: str) -> str:
    prev = None
    cur = text
    while prev != cur:
        prev = cur
        cur = re.sub(r".\x08", "", cur)
    return cur


def pascal_to_kebab(name: str) -> str:
    name = name.strip().replace("_", "-")
    if "-" in name and name.lower() == name:
        return name
    s1 = re.sub(r"(.)([A-Z][a-z]+)", r"\1-\2", name)
    s2 = re.sub(r"([a-z0-9])([A-Z])", r"\1-\2", s1)
    return s2.lower()


def kebab_to_pascal(name: str) -> str:
    chunks = [c for c in name.strip().split("-") if c]
    return "".join(chunk[:1].upper() + chunk[1:] for chunk in chunks)


def normalize_operation_id(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", name.strip().lower())


def parse_ops_file(path: Path) -> list[str]:
    src = path.read_text(encoding="utf-8")
    names = re.findall(r'\{[^}]*\bName:\s*"([^"]+)"', src)
    deduped: list[str] = []
    seen: set[str] = set()
    for name in names:
        if name in seen:
            continue
        seen.add(name)
        deduped.append(name)
    return deduped


def cloudfront_raw_fallback_routes() -> dict[str, tuple[str, str]]:
    global _CLOUDFRONT_RAW_FALLBACK_ROUTES  # noqa: PLW0603

    if _CLOUDFRONT_RAW_FALLBACK_ROUTES is not None:
        return _CLOUDFRONT_RAW_FALLBACK_ROUTES

    routes: dict[str, tuple[str, str]] = {}
    ops_path = REPO_ROOT / "internal/server/cloudfront_ops.go"
    if ops_path.exists():
        src = ops_path.read_text(encoding="utf-8")
        pattern = re.compile(
            r'\{[^}]*\bName:\s*"([^"]+)"[^}]*\bMethod:\s*"([^"]+)"[^}]*\bURI:\s*"([^"]+)"[^}]*\}',
            re.MULTILINE,
        )
        for name, method, uri in pattern.findall(src):
            method = method.strip().upper()
            uri = uri.strip()
            if name and method and uri:
                routes[name] = (method, uri)
    _CLOUDFRONT_RAW_FALLBACK_ROUTES = routes
    return routes


