def filter_output_schema_errors(endpoint: Endpoint, errors: list[str]) -> list[str]:
    if endpoint.service == "sqs" and endpoint.operation == "SendMessageBatch":
        return [err for err in errors if err != "$.Failed: missing required field"]
    if endpoint.service == "s3" and endpoint.operation == "ListParts":
        return [err for err in errors if err != "$.ChecksumType: unknown field"]
    if endpoint.service == "cognitouserpools" and endpoint.operation in {"CreateUserPoolDomain", "UpdateUserPoolDomain"}:
        return [err for err in errors if err != "$.ManagedLoginVersion: unknown field"]
    if endpoint.service == "controltower" and endpoint.operation == "GetControlOperation":
        return [err for err in errors if err != "$.controlOperation.operationIdentifier: unknown field"]
    if endpoint.service == "controltower" and endpoint.operation == "GetLandingZoneOperation":
        return [err for err in errors if err != "$.operationDetails.operationIdentifier: unknown field"]
    return errors


def validate_output_schema(endpoint: Endpoint, stdout_text: str) -> str | None:
    op_model = get_operation_model(endpoint)
    output_shape = getattr(op_model, "output_shape", None) if op_model is not None else None
    if output_shape is None:
        return None

    text = stdout_text.strip()
    if not text:
        if output_schema_allows_empty_stdout(endpoint):
            return None
        if (
            str(getattr(output_shape, "type_name", "")).lower() == "structure"
            and not (getattr(output_shape, "members", {}) or {})
        ):
            return None
        return "empty output"
    try:
        data = json.loads(text)
    except json.JSONDecodeError as err:
        return f"non-json output: {err}"

    errors: list[str] = []

    def _validate(shape, value, path: str) -> None:
        if shape is None:
            return
        if bool(getattr(shape, "is_document_type", False)):
            return
        type_name = str(getattr(shape, "type_name", "")).lower()
        label = path or "$"

        if type_name == "structure":
            if not isinstance(value, dict):
                errors.append(f"{label}: expected object")
                return
            members = getattr(shape, "members", {}) or {}
            required = set(getattr(shape, "required_members", []) or [])
            for name in required:
                if name not in value:
                    errors.append(f"{label}.{name}: missing required field")
            for key, item in value.items():
                member_shape = members.get(key)
                if member_shape is None:
                    errors.append(f"{label}.{key}: unknown field")
                    continue
                if item is None and key not in required:
                    continue
                _validate(member_shape, item, f"{label}.{key}")
            return

        if type_name == "list":
            if not isinstance(value, list):
                errors.append(f"{label}: expected list")
                return
            member_shape = getattr(shape, "member", None)
            for idx, item in enumerate(value[:10]):
                _validate(member_shape, item, f"{label}[{idx}]")
            return

        if type_name == "map":
            if not isinstance(value, dict):
                errors.append(f"{label}: expected map")
                return
            value_shape = getattr(shape, "value", None)
            for key, item in list(value.items())[:10]:
                _validate(value_shape, item, f"{label}[{key}]")
            return

        if type_name in {"string", "character", "blob"}:
            if not isinstance(value, str):
                errors.append(f"{label}: expected string")
            return
        if type_name in {"integer", "long", "short", "byte"}:
            if not (isinstance(value, int) and not isinstance(value, bool)):
                errors.append(f"{label}: expected integer")
            return
        if type_name in {"float", "double"}:
            if not ((isinstance(value, int) or isinstance(value, float)) and not isinstance(value, bool)):
                errors.append(f"{label}: expected number")
            return
        if type_name == "boolean":
            if not isinstance(value, bool):
                errors.append(f"{label}: expected boolean")
            return
        if type_name == "timestamp":
            if not isinstance(value, (str, int, float)):
                errors.append(f"{label}: expected timestamp")
            return

    _validate(output_shape, data, "")
    errors = filter_output_schema_errors(endpoint, errors)
    if not errors:
        return None
    if len(errors) > 3:
        return "; ".join(errors[:3]) + f" (+{len(errors)-3} more)"
    return "; ".join(errors)


def ec2_runtime_ids() -> dict[str, list[str]]:
    state = RUNTIME_STATE.setdefault("ec2", {})
    ids = state.get("ids")
    if not isinstance(ids, dict):
        ids = {}
        state["ids"] = ids
    normalized: dict[str, list[str]] = {}
    for key, values in ids.items():
        if isinstance(key, str) and isinstance(values, list):
            clean = [str(v) for v in values if isinstance(v, str) and v.strip()]
            if clean:
                normalized[key] = clean
    state["ids"] = normalized
    return normalized


def ec2_add_runtime_value(key: str, value: str) -> None:
    norm_key = key.strip().lower()
    norm_value = value.strip()
    if not norm_key or not norm_value:
        return
    if norm_value.lower() in {"stackyard", "x", "xx", "xxx", "xxxx"}:
        return
    if norm_key.endswith("id") and "-" not in norm_value:
        return
    if "." in norm_value and norm_key.endswith("id"):
        # Avoid recording endpoint DNS names into *Id slots (for example ClientVpnEndpointId).
        return
    if norm_key == "transitgatewayid":
        lowered = norm_value.lower()
        # Keep attachment/route-table/multicast/peer ids out of the primary TGW id bucket.
        if any(token in lowered for token in ("attach", "rtb", "mcast", "domain", "peer")):
            return
    ids = ec2_runtime_ids()
    bucket = ids.setdefault(norm_key, [])
    if norm_value not in bucket:
        bucket.insert(0, norm_value)
    for alias in EC2_KEY_ALIASES.get(norm_key, []):
        alias_bucket = ids.setdefault(alias, [])
        if norm_value not in alias_bucket:
            alias_bucket.insert(0, norm_value)


