def ec2_record_runtime_payload(payload) -> None:
    def _walk(node):
        if isinstance(node, dict):
            for key, value in node.items():
                key_lower = str(key).strip().lower()
                if key_lower.endswith("id") and isinstance(value, str):
                    ec2_add_runtime_value(key_lower, value)
                    guessed = ec2_guess_runtime_key_from_id(value)
                    if guessed:
                        ec2_add_runtime_value(guessed, value)
                elif key_lower.endswith("ids") and isinstance(value, list):
                    singular = key_lower[:-1]
                    for item in value:
                        if isinstance(item, str):
                            ec2_add_runtime_value(singular, item)
                            guessed = ec2_guess_runtime_key_from_id(item)
                            if guessed:
                                ec2_add_runtime_value(guessed, item)
                elif key_lower.endswith("name") and isinstance(value, str):
                    ec2_add_runtime_value(key_lower, value)
                _walk(value)
        elif isinstance(node, list):
            for item in node:
                _walk(item)
        elif isinstance(node, str):
            guessed = ec2_guess_runtime_key_from_id(node)
            if guessed:
                ec2_add_runtime_value(guessed, node)

    _walk(payload)


def ec2_xml_tag_name(tag: str) -> str:
    clean = str(tag).strip()
    if "}" in clean:
        clean = clean.rsplit("}", 1)[-1]
    if ":" in clean:
        clean = clean.rsplit(":", 1)[-1]
    if not clean:
        return clean
    return clean[:1].upper() + clean[1:]


def ec2_parse_xml_payload(response_text: str) -> dict[str, object] | None:
    text = str(response_text).strip()
    if not text or "<" not in text:
        return None
    try:
        root = xml_etree.fromstring(text)
    except xml_etree.ParseError:
        return None

    def _convert(element):
        children = list(element)
        if not children:
            return (element.text or "").strip()

        child_tags = [ec2_xml_tag_name(child.tag) for child in children]
        if child_tags and all(tag in {"Item", "Member"} for tag in child_tags):
            return [_convert(child) for child in children]

        out: dict[str, object] = {}
        for child in children:
            child_name = ec2_xml_tag_name(child.tag)
            child_value = _convert(child)
            if child_name in out:
                existing = out[child_name]
                if isinstance(existing, list):
                    existing.append(child_value)
                else:
                    out[child_name] = [existing, child_value]
            else:
                out[child_name] = child_value
        return out

    converted = _convert(root)
    if isinstance(converted, dict):
        return converted
    return {ec2_xml_tag_name(root.tag): converted}


def ec2_record_runtime_xml(response_text: str) -> dict[str, object] | None:
    parsed = ec2_parse_xml_payload(response_text)
    if isinstance(parsed, dict):
        ec2_record_runtime_payload(parsed)
        for response_key, runtime_key in (
            ("TransitGatewayConnect", "transitgatewayconnectid"),
            ("TransitGatewayPeeringAttachment", "transitgatewaypeeringattachmentid"),
            ("TransitGatewayVpcAttachment", "transitgatewayvpcattachmentid"),
        ):
            value = parsed.get(response_key)
            if not isinstance(value, dict):
                continue
            attachment_id = value.get("TransitGatewayAttachmentId")
            if isinstance(attachment_id, str) and attachment_id.strip():
                ec2_add_runtime_value(runtime_key, attachment_id)
    for token in re.findall(r"\b[a-z][a-z0-9-]{5,}\b", response_text):
        guessed = ec2_guess_runtime_key_from_id(token)
        if guessed:
            ec2_add_runtime_value(guessed, token)
    return parsed


def ec2_reset_runtime_state() -> None:
    state = RUNTIME_STATE.setdefault("ec2", {})
    state["seeded"] = False
    state["ids"] = {}


def ec2_get_runtime_value(key: str) -> str:
    key_lower = key.strip().lower()
    if key_lower in EC2_PREFER_DEFAULT_KEYS:
        return EC2_DEFAULT_KEY_VALUES.get(key_lower, "stackyard")
    ids = ec2_runtime_ids()
    candidate_keys = [key_lower, *EC2_KEY_ALIASES.get(key_lower, [])]
    for candidate in candidate_keys:
        values = ids.get(candidate)
        if isinstance(values, list):
            for value in values:
                if isinstance(value, str) and value.strip():
                    return value
    return EC2_DEFAULT_KEY_VALUES.get(key_lower, "stackyard")


def ec2_get_primary_transit_gateway_id() -> str:
    ids = ec2_runtime_ids().get("transitgatewayid")
    if isinstance(ids, list):
        for value in ids:
            if not isinstance(value, str):
                continue
            value = value.strip()
            if not value:
                continue
            lowered = value.lower()
            if "peer" in lowered or "attach" in lowered or "rtb" in lowered or "mcast" in lowered or "domain" in lowered:
                continue
            if not re.match(r"^tgw-[a-z0-9]+$", lowered):
                continue
            return value
    return ec2_get_runtime_value("transitgatewayid")


def ec2_ensure_capacity_reservation_id(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    reservation_id = ""
    reservation_data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ec2",
        "create-capacity-reservation",
        env,
        [
            "--instance-type",
            "m5.large",
            "--instance-platform",
            "Linux/UNIX",
            "--availability-zone",
            "us-east-1a",
            "--instance-count",
            "1",
            "--tenancy",
            "default",
            "--instance-match-criteria",
            "open",
        ],
    )
    if isinstance(reservation_data, dict):
        ec2_record_runtime_payload(reservation_data)
        reservation = reservation_data.get("CapacityReservation")
        if isinstance(reservation, dict):
            value = reservation.get("CapacityReservationId")
            if isinstance(value, str) and value.strip():
                reservation_id = value
    if not reservation_id:
        reservation_id = ec2_get_runtime_value("capacityreservationid")
    return reservation_id


def ec2_payload_placeholder(value) -> bool:
    if value is None:
        return True
    if isinstance(value, str):
        lowered = value.strip().lower()
        return lowered in {"", "stackyard", "x", "xx", "xxx", "xxxx"}
    return False


def ec2_replacement_for_key(key: str, path: tuple[str, ...]) -> object:
    key_lower = key.strip().lower()
    parent = path[-1].lower() if path else ""
    if key_lower == "nexttoken":
        return ""
    if key_lower in {"dryrun"}:
        return False
    if key_lower in {"publickeymaterial", "uploadpolicy", "uploadpolicysignature"}:
        return "c3RhY2t5YXJk"
    if key_lower == "userdata":
        return "c3RhY2t5YXJk"
    if key_lower == "value" and parent in {"userdata", "kernel", "ramdisk"}:
        return "c3RhY2t5YXJk"
    if key_lower == "groupname":
        return "default"
    if key_lower == "clientcidrblock":
        return "10.99.0.0/22"
    if key_lower == "targetvpcsubnetid":
        return ec2_get_runtime_value("subnetid")
    if key_lower == "sourceipampoolid":
        return ec2_get_runtime_value("ipampoolid")
    if key_lower == "locale":
        return "us-east-1"
    if key_lower == "launchtemplatename":
        return ec2_get_runtime_value("launchtemplatename")
    if key_lower == "sourceversion":
        return "1"
    if key_lower == "addressfamily":
        return "ipv4"
    if key_lower == "vpnport":
        return 443
    if key_lower == "amazonsideasn":
        return 64512
    if key_lower == "sessiontimeouthours":
        return 24
    if key_lower in {"bucket", "s3bucket", "s3bucketname"}:
        return "stackyard"
    if key_lower in {"prefix", "s3prefix"}:
        return "stackyard"
    if key_lower in {"ipprotocol", "protocol"}:
        return "tcp"
    if key_lower in {"cidr", "cidrip", "cidripv4"}:
        return "10.0.0.0/24"
    if key_lower == "ipaddress":
        return "198.51.100.10"
    if key_lower == "destinationcidrblock":
        return "10.0.0.0/16"
    if key_lower == "destinationipv6cidrblock":
        return "2001:db8::/64"
    if key_lower == "publicip":
        return "198.51.100.10"
    if key_lower == "privateipaddress":
        return "10.0.0.10"
    if key_lower == "peeraddress":
        return "198.51.100.20"
    if key_lower == "transitgatewayaddress":
        return "169.254.100.1"
    if key_lower == "availabilityzone":
        return "us-east-1a"
    if key_lower == "availabilityzoneid":
        return "use1-az1"
    if key_lower == "key" and parent == "dhcpconfigurations":
        return "domain-name-servers"
    if key_lower == "values" and parent == "dhcpconfigurations":
        return ["AmazonProvidedDNS"]
    if key_lower == "insidecidrblocks":
        return ["169.254.10.0/29"]
    if key_lower == "connectionevents":
        return ["Accept"]
    if key_lower in {"networkloadbalancerarn", "loadbalancerarn"}:
        return "arn:aws:elasticloadbalancing:us-east-1:123456789012:loadbalancer/net/stackyard/1234567890abcdef"
    if key_lower == "connectionnotificationarn":
        return "arn:aws:sns:us-east-1:123456789012:stackyard"
    if key_lower == "lambdafunctionarn":
        return "arn:aws:lambda:us-east-1:123456789012:function:stackyard"
    if key_lower == "loggrouparn":
        return "arn:aws:logs:us-east-1:123456789012:log-group:stackyard"
    if key_lower == "kmskeyarn":
        return "arn:aws:kms:us-east-1:123456789012:key/stackyard"
    if key_lower in {"servercertificatearn", "clientrootcertificatechainarn", "certificatearn"}:
        return "arn:aws:acm:us-east-1:123456789012:certificate/stackyard"
    if key_lower.endswith("arns"):
        singular = key_lower[:-1]
        value = ec2_replacement_for_key(singular, path)
        if isinstance(value, str):
            return [value]
        return []
    if key_lower.endswith("arn"):
        return "arn:aws:ec2:us-east-1:123456789012:resource/stackyard"
    if key_lower.endswith("id"):
        return ec2_get_runtime_value(key_lower)
    if key_lower.endswith("ids"):
        singular = key_lower[:-1]
        return [ec2_get_runtime_value(singular)]
    return "stackyard"


def ec2_hydrate_payload(payload, path: tuple[str, ...] = ()) -> object:
    if isinstance(payload, dict):
        out: dict[str, object] = {}
        for key, value in payload.items():
            key_lower = str(key).strip().lower()
            if key_lower == "filters":
                # Empty skeleton filter names are invalid for many APIs; skip filters.
                out[key] = []
                continue
            if key_lower == "tagspecifications":
                # Tags are optional in coverage probes and often produce invalid resource-type combinations.
                out[key] = []
                continue
            if key_lower == "blockdevicemappings":
                # Optional in most APIs and frequently populated with invalid nested placeholders.
                out[key] = []
                continue
            hydrated = ec2_hydrate_payload(value, (*path, str(key)))
            if isinstance(hydrated, list) and key_lower.endswith("ids"):
                if len(hydrated) == 1 and isinstance(hydrated[0], list):
                    nested = hydrated[0]
                    if nested and isinstance(nested[0], str):
                        hydrated = [nested[0]]
                if not hydrated:
                    hydrated = [ec2_get_runtime_value(key_lower[:-1])]
                elif len(hydrated) == 1 and ec2_payload_placeholder(hydrated[0]):
                    hydrated = [ec2_get_runtime_value(key_lower[:-1])]
            if isinstance(hydrated, list) and key_lower.endswith("arns"):
                if not hydrated:
                    replacement = ec2_replacement_for_key(str(key), path)
                    if isinstance(replacement, list):
                        hydrated = replacement
                elif len(hydrated) == 1 and ec2_payload_placeholder(hydrated[0]):
                    replacement = ec2_replacement_for_key(str(key), path)
                    if isinstance(replacement, list):
                        hydrated = replacement
            if isinstance(hydrated, str) and ec2_payload_placeholder(hydrated):
                hydrated = ec2_replacement_for_key(str(key), path)
            if hydrated is None and key_lower.endswith(("id", "ids", "name", "names")):
                hydrated = ec2_replacement_for_key(str(key), path)
            out[key] = hydrated
        return out
    if isinstance(payload, list):
        out_items = [ec2_hydrate_payload(item, path) for item in payload]
        # Collapse placeholder-only lists to empty to avoid invalid shape/value errors.
        if out_items and all(ec2_payload_placeholder(item) for item in out_items):
            return []
        return out_items
    if ec2_payload_placeholder(payload):
        current = path[-1] if path else ""
        if current.lower().endswith("ids"):
            current = current[:-1]
        return ec2_replacement_for_key(current, path[:-1] if path else ())
    return payload


def ec2_seed_runtime_state(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> None:
    state = RUNTIME_STATE.setdefault("ec2", {})
    if state.get("seeded"):
        return
    for key, value in EC2_DEFAULT_KEY_VALUES.items():
        ec2_add_runtime_value(key, value)

    def _capture(operation: str, args: Sequence[str] | None = None) -> dict | None:
        endpoint = Endpoint(
            service="ec2",
            cli_service="ec2",
            operation=kebab_to_pascal(operation),
            cli_operation=operation,
            source="seed",
        )

        def _raw_capture() -> dict | None:
            input_payload, _ = generate_cli_input_payload(aws_bin, endpoint, env)
            if isinstance(input_payload, dict):
                payload = copy.deepcopy(input_payload)
            else:
                payload = build_raw_fallback_payload(endpoint)
            if not isinstance(payload, dict):
                return None
            payload = apply_service_payload_tweaks(endpoint, payload)
            payload = ec2_hydrate_payload(payload)
            if not isinstance(payload, dict):
                return None
            status_code, response_text = invoke_raw_endpoint(endpoint, endpoint_url, region, env, payload)
            if not (200 <= status_code < 300):
                return None
            parsed = ec2_record_runtime_xml(response_text)
            return parsed if isinstance(parsed, dict) else {}

        if endpoint.operation in EC2_FORCE_RAW_FALLBACK_OPERATIONS:
            return _raw_capture()

        data = run_aws_json(aws_bin, endpoint_url, region, "ec2", operation, env, args)
        if isinstance(data, dict):
            ec2_record_runtime_payload(data)
            return data
        return _raw_capture()

    # Pull currently available IDs first.
    _capture("describe-vpcs")
    _capture("describe-subnets")
    _capture("describe-route-tables")
    _capture("describe-network-acls")
    _capture("describe-dhcp-options")
    _capture("describe-security-groups")
    _capture("describe-network-interfaces")
    _capture("describe-volumes")
    _capture("describe-snapshots")
    _capture("describe-addresses")
    _capture("describe-transit-gateways")
    _capture("describe-transit-gateway-vpc-attachments")
    _capture("describe-transit-gateway-attachments")
    _capture("describe-transit-gateway-route-tables")
    _capture("describe-client-vpn-endpoints")
    _capture("describe-launch-templates")
    _capture("describe-instances")
    _capture("describe-images")
    _capture("describe-coip-pools")
    _capture("describe-instance-event-windows")
    _capture("describe-hosts")

    if ec2_get_runtime_value("vpcid") == EC2_DEFAULT_KEY_VALUES["vpcid"]:
        _capture("create-vpc", ["--cidr-block", "10.0.0.0/16"])
    if ec2_get_runtime_value("subnetid") == EC2_DEFAULT_KEY_VALUES["subnetid"]:
        _capture(
            "create-subnet",
            ["--vpc-id", ec2_get_runtime_value("vpcid"), "--cidr-block", "10.0.1.0/24"],
        )
    if ec2_get_runtime_value("routetableid") == EC2_DEFAULT_KEY_VALUES["routetableid"]:
        _capture("create-route-table", ["--vpc-id", ec2_get_runtime_value("vpcid")])
    if ec2_get_runtime_value("networkaclid") == EC2_DEFAULT_KEY_VALUES["networkaclid"]:
        _capture("create-network-acl", ["--vpc-id", ec2_get_runtime_value("vpcid")])
    if ec2_get_runtime_value("groupid") == EC2_DEFAULT_KEY_VALUES["groupid"]:
        _capture(
            "create-security-group",
            [
                "--group-name",
                f"stackyard-sg-{int(time.time())}",
                "--description",
                "stackyard seed security group",
                "--vpc-id",
                ec2_get_runtime_value("vpcid"),
            ],
        )
    if ec2_get_runtime_value("internetgatewayid") == EC2_DEFAULT_KEY_VALUES["internetgatewayid"]:
        _capture("create-internet-gateway")
