def apply_service_payload_tweaks(endpoint: Endpoint, payload):
    if not isinstance(payload, dict):
        return payload

    if endpoint.service == "s3control":
        payload = normalize_account_id_fields(payload, S3CONTROL_COVERAGE_ACCOUNT_ID)

    if endpoint.service == "flink":
        def _sanitize_flink_blob_fields(node: object) -> None:
            if isinstance(node, dict):
                for key, value in node.items():
                    lowered = str(key).lower()
                    if lowered in {"zipfilecontent", "zipfilecontentupdate"} and isinstance(value, str):
                        if not is_valid_base64_string(value):
                            node[key] = "c3RhY2t5YXJk"
                        continue
                    _sanitize_flink_blob_fields(value)
            elif isinstance(node, list):
                for item in node:
                    _sanitize_flink_blob_fields(item)

        _sanitize_flink_blob_fields(payload)

    if endpoint.service == "blockchain":
        default_network = "ETHEREUM_MAINNET"
        default_contract = "0x0000000000000000000000000000000000000000"
        default_owner = "0x1111111111111111111111111111111111111111"
        default_tx_hash = "0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"

        set_key_if_present_case_insensitive(payload, "network", default_network)
        set_key_if_present_case_insensitive(payload, "address", default_owner)
        set_key_if_present_case_insensitive(payload, "transactionHash", default_tx_hash)
        set_key_if_present_case_insensitive(payload, "transactionId", "stackyard-txid-000001")
        set_key_if_present_case_insensitive(payload, "maxResults", 10)
        delete_key_if_present_case_insensitive(payload, "nextToken")

        def _sanitize_blockchain_fields(node: object) -> None:
            if isinstance(node, dict):
                for key, value in node.items():
                    lowered = str(key).lower()
                    if lowered == "network":
                        node[key] = default_network
                        continue
                    if lowered == "contractaddress" and (not isinstance(value, str) or not value.strip()):
                        node[key] = default_contract
                        continue
                    if lowered == "tokenid" and (not isinstance(value, str) or not value.strip()):
                        node[key] = "1"
                        continue
                    if lowered == "deployeraddress" and (not isinstance(value, str) or not value.strip()):
                        node[key] = default_owner
                        continue
                    if lowered == "address" and (not isinstance(value, str) or not value.strip()):
                        node[key] = default_owner
                        continue
                    if lowered == "transactionhash" and (not isinstance(value, str) or not value.strip()):
                        node[key] = default_tx_hash
                        continue
                    if lowered == "transactionid" and (not isinstance(value, str) or not value.strip()):
                        node[key] = "stackyard-txid-000001"
                        continue
                    if lowered == "transactioneventtoaddress" and isinstance(value, list):
                        node[key] = [default_owner]
                        continue
                    _sanitize_blockchain_fields(value)
            elif isinstance(node, list):
                if not node:
                    return
                for item in node:
                    _sanitize_blockchain_fields(item)

        _sanitize_blockchain_fields(payload)

