        def _is_valid_b64(text: str) -> bool:
            try:
                base64.b64decode(text, validate=True)
                return True
            except Exception:  # noqa: BLE001
                return False

        def _sanitize_binary_values(value: object) -> None:
            if isinstance(value, dict):
                for key, child in value.items():
                    lowered = str(key).lower()
                    if lowered == "b" and isinstance(child, str):
                        if not _is_valid_b64(child):
                            value[key] = "c3RhY2t5YXJk"
                        continue
                    if lowered == "bs" and isinstance(child, list):
                        out: list[str] = []
                        for item in child:
                            if isinstance(item, str) and _is_valid_b64(item):
                                out.append(item)
                            else:
                                out.append("c3RhY2t5YXJk")
                        value[key] = out or ["c3RhY2t5YXJk"]
                        continue
                    _sanitize_binary_values(child)
            elif isinstance(value, list):
                for item in value:
                    _sanitize_binary_values(item)

        _sanitize_binary_values(payload)

