def s3tables_ensure_table_record_expiration(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    bucket_arn, namespace, table_name = s3tables_ensure_table(aws_bin, endpoint_url, region, env)
    table_arn = s3tables_table_arn(bucket_arn, namespace, table_name)
    s3tables_invoke_raw_operation(
        endpoint_url,
        region,
        env,
        "PutTableRecordExpirationConfiguration",
        {"tableArn": table_arn, "recordExpiration": "30d"},
    )
    return table_arn


def cognitosync_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("cognitosync", {})
    safe_region = region.strip() or "us-east-1"
    defaults = {
        "region": safe_region,
        "identity_pool_id": f"{safe_region}:stackyard-cognitosync-pool",
        "identity_id": f"{safe_region}:stackyard-cognitosync-identity",
        "dataset_name": COGNITOSYNC_DEFAULT_DATASET_NAME,
        "device_platform": COGNITOSYNC_DEFAULT_DEVICE_PLATFORM,
        "device_token": COGNITOSYNC_DEFAULT_DEVICE_TOKEN,
        "device_id": COGNITOSYNC_DEFAULT_DEVICE_ID,
        "push_role_arn": COGNITOSYNC_DEFAULT_PUSH_ROLE_ARN,
        "stream_role_arn": COGNITOSYNC_DEFAULT_STREAM_ROLE_ARN,
        "application_arn": COGNITOSYNC_DEFAULT_APPLICATION_ARN,
        "stream_name": COGNITOSYNC_DEFAULT_STREAM_NAME,
        "event_arn": COGNITOSYNC_DEFAULT_EVENT_ARN,
        "max_results": 10,
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def cognitosync_record_runtime_payload(region: str, payload: object) -> None:
    state = cognitosync_runtime_state(region)
    if not isinstance(payload, dict):
        return

    def _record(key: str, value: object) -> None:
        if isinstance(value, str) and value.strip():
            state[key] = value.strip()

    _record("identity_pool_id", payload.get("IdentityPoolId"))
    _record("identity_id", payload.get("IdentityId"))
    _record("device_id", payload.get("DeviceId"))
    _record("sync_session_token", payload.get("SyncSessionToken"))

    dataset = payload.get("Dataset")
    if isinstance(dataset, dict):
        _record("identity_pool_id", dataset.get("IdentityPoolId"))
        _record("identity_id", dataset.get("IdentityId"))
        _record("dataset_name", dataset.get("DatasetName"))

    datasets = payload.get("Datasets")
    if isinstance(datasets, list):
        for item in datasets:
            if not isinstance(item, dict):
                continue
            _record("dataset_name", item.get("DatasetName"))
            if str(state.get("dataset_name", "")).strip():
                break


def cognitosync_ensure_device(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    identity_pool_id: str,
    identity_id: str,
    platform: str,
    token: str,
) -> str:
    state = cognitosync_runtime_state(region)
    registered = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cognito-sync",
        "register-device",
        env,
        [
            "--identity-pool-id",
            identity_pool_id,
            "--identity-id",
            identity_id,
            "--platform",
            platform,
            "--token",
            token,
        ],
    )
    if isinstance(registered, dict):
        cognitosync_record_runtime_payload(region, registered)
    device_id = str(state.get("device_id") or "").strip()
    if device_id:
        return device_id
    return COGNITOSYNC_DEFAULT_DEVICE_ID


