def cognitouserpools_ensure_resource_server(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    user_pool_id: str,
) -> tuple[str, str]:
    state = cognitouserpools_runtime_state(region)
    identifier = str(state.get("resource_server_identifier") or COGNITOUSERPOOLS_DEFAULT_RESOURCE_SERVER_IDENTIFIER).strip() or COGNITOUSERPOOLS_DEFAULT_RESOURCE_SERVER_IDENTIFIER
    name = str(state.get("resource_server_name") or COGNITOUSERPOOLS_DEFAULT_RESOURCE_SERVER_NAME).strip() or COGNITOUSERPOOLS_DEFAULT_RESOURCE_SERVER_NAME
    described = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cognito-idp",
        "describe-resource-server",
        env,
        [
            "--user-pool-id",
            user_pool_id,
            "--identifier",
            identifier,
        ],
    )
    if isinstance(described, dict):
        cognitouserpools_record_runtime_payload(region, described)
        return identifier, name

    create_payload = {
        "UserPoolId": user_pool_id,
        "Identifier": identifier,
        "Name": name,
        "Scopes": [{"ScopeName": "read", "ScopeDescription": "Read scope"}],
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cognito-idp",
        "create-resource-server",
        env,
        ["--cli-input-json", json.dumps(create_payload, separators=(",", ":"))],
    )
    if isinstance(created, dict):
        cognitouserpools_record_runtime_payload(region, created)
        return (
            str(state.get("resource_server_identifier") or identifier).strip() or identifier,
            str(state.get("resource_server_name") or name).strip() or name,
        )

    listed = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cognito-idp",
        "list-resource-servers",
        env,
        ["--user-pool-id", user_pool_id, "--max-results", "60"],
    )
    if isinstance(listed, dict):
        cognitouserpools_record_runtime_payload(region, listed)
    return (
        str(state.get("resource_server_identifier") or identifier).strip() or identifier,
        str(state.get("resource_server_name") or name).strip() or name,
    )


def cognitouserpools_ensure_domain(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    user_pool_id: str,
) -> str:
    state = cognitouserpools_runtime_state(region)
    configured_domain = str(state.get("domain") or COGNITOUSERPOOLS_DEFAULT_DOMAIN).strip() or COGNITOUSERPOOLS_DEFAULT_DOMAIN
    unique = str(int(time.time() * 1000) % 1000000).zfill(6)
    pool_suffix = re.sub(r"[^a-z0-9-]", "", user_pool_id.lower().replace("_", "-"))[:24]
    candidate_domains = [configured_domain, f"stackyard-auth-{pool_suffix}-{unique}"]
    for domain in candidate_domains:
        if not domain:
            continue
        described = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "cognito-idp",
            "describe-user-pool-domain",
            env,
            ["--domain", domain],
        )
        if isinstance(described, dict):
            cognitouserpools_record_runtime_payload(region, described)
            domain_description = described.get("DomainDescription")
            if isinstance(domain_description, dict):
                owner_pool_id = str(domain_description.get("UserPoolId") or "").strip()
                if owner_pool_id == user_pool_id:
                    state["domain"] = domain
                    return domain
                continue
        created = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "cognito-idp",
            "create-user-pool-domain",
            env,
            [
                "--user-pool-id",
                user_pool_id,
                "--domain",
                domain,
            ],
        )
        if isinstance(created, dict):
            state["domain"] = domain
            return domain
    fallback = str(state.get("domain") or configured_domain).strip() or configured_domain
    state["domain"] = fallback
    return fallback


