def cognitouserpools_ensure_device(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    user_pool_id: str,
    client_id: str,
) -> str:
    state = cognitouserpools_runtime_state(region)
    access_token, _, _ = cognitouserpools_ensure_auth_tokens(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    device_key = str(state.get("device_key") or "device-1").strip() or "device-1"
    confirm_payload = {
        "AccessToken": access_token,
        "DeviceKey": device_key,
        "DeviceName": "coverage-device",
        "DeviceSecretVerifierConfig": {
            "Salt": "c3RhY2t5YXJk",
            "PasswordVerifier": "c3RhY2t5YXJk",
        },
    }
    confirmed = cognitouserpools_invoke_raw_json(
        operation="ConfirmDevice",
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        payload=confirm_payload,
    )
    if isinstance(confirmed, dict):
        state["device_key"] = device_key
    got = cognitouserpools_invoke_raw_json(
        operation="GetDevice",
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        payload={
            "AccessToken": access_token,
            "DeviceKey": device_key,
        },
    )
    if isinstance(got, dict):
        cognitouserpools_record_runtime_payload(region, got)
    return str(state.get("device_key") or device_key).strip() or device_key


def cognitouserpools_ensure_webauthn_credential(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    user_pool_id: str,
    client_id: str,
) -> str:
    state = cognitouserpools_runtime_state(region)
    access_token, _, _ = cognitouserpools_ensure_auth_tokens(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    listed = cognitouserpools_invoke_raw_json(
        operation="ListWebAuthnCredentials",
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        payload={
            "AccessToken": access_token,
            "MaxResults": 10,
        },
    )
    if isinstance(listed, dict):
        cognitouserpools_record_runtime_payload(region, listed)
        current = str(state.get("credential_id") or "").strip()
        if current and current != "credential-1":
            return current

    started = cognitouserpools_invoke_raw_json(
        operation="StartWebAuthnRegistration",
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        payload={"AccessToken": access_token},
    )
    if isinstance(started, dict):
        cognitouserpools_record_runtime_payload(region, started)

    session = str(state.get("session") or "").strip()
    complete_payload = {
        "AccessToken": access_token,
        "Session": session,
        "Credential": "c3RhY2t5YXJk",
        "FriendlyName": "coverage-passkey",
    }
    completed = cognitouserpools_invoke_raw_json(
        operation="CompleteWebAuthnRegistration",
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        payload=complete_payload,
    )
    if isinstance(completed, dict):
        cognitouserpools_record_runtime_payload(region, completed)
        current = str(state.get("credential_id") or "").strip()
        if current and current != "credential-1":
            return current

    listed = cognitouserpools_invoke_raw_json(
        operation="ListWebAuthnCredentials",
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        payload={
            "AccessToken": access_token,
            "MaxResults": 10,
        },
    )
    if isinstance(listed, dict):
        cognitouserpools_record_runtime_payload(region, listed)
    fallback = str(state.get("credential_id") or "credential-1").strip() or "credential-1"
    state["credential_id"] = fallback
    return fallback


def cognitouserpools_prepare_complete_webauthn_registration(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    user_pool_id: str,
    client_id: str,
) -> str:
    state = cognitouserpools_runtime_state(region)
    access_token, _, _ = cognitouserpools_ensure_auth_tokens(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    started = cognitouserpools_invoke_raw_json(
        operation="StartWebAuthnRegistration",
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        payload={"AccessToken": access_token},
    )
    if isinstance(started, dict):
        cognitouserpools_record_runtime_payload(region, started)
    session = str(state.get("session") or "").strip()
    if not session:
        state["session"] = COGNITOUSERPOOLS_DEFAULT_SESSION
        return COGNITOUSERPOOLS_DEFAULT_SESSION
    return session


