def cognitouserpools_seed_for_operation(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    operation: str,
) -> None:
    if operation in {"CreateUserPool", "ListUserPools"}:
        return

    user_pool_id, _ = cognitouserpools_ensure_user_pool(aws_bin, endpoint_url, region, env)
    if not user_pool_id:
        return
    client_id = ""
    if operation != "CreateUserPoolClient":
        client_id = cognitouserpools_ensure_user_pool_client(aws_bin, endpoint_url, region, env, user_pool_id)

    if operation in {
        "DescribeUserPoolDomain",
        "DeleteUserPoolDomain",
        "UpdateUserPoolDomain",
    }:
        cognitouserpools_ensure_domain(aws_bin, endpoint_url, region, env, user_pool_id)
    if operation in {
        "GetGroup",
        "UpdateGroup",
        "DeleteGroup",
        "ListUsersInGroup",
        "AdminAddUserToGroup",
        "AdminRemoveUserFromGroup",
    }:
        cognitouserpools_ensure_group(aws_bin, endpoint_url, region, env, user_pool_id)
    if operation in {
        "DescribeIdentityProvider",
        "DeleteIdentityProvider",
        "GetIdentityProviderByIdentifier",
        "UpdateIdentityProvider",
    }:
        cognitouserpools_ensure_identity_provider(aws_bin, endpoint_url, region, env, user_pool_id)
    if operation in {
        "DescribeResourceServer",
        "DeleteResourceServer",
        "UpdateResourceServer",
    }:
        cognitouserpools_ensure_resource_server(aws_bin, endpoint_url, region, env, user_pool_id)
    if operation in {
        "DescribeUserImportJob",
        "StartUserImportJob",
        "StopUserImportJob",
    }:
        cognitouserpools_ensure_import_job(aws_bin, endpoint_url, region, env, user_pool_id)
    if operation in {
        "UpdateManagedLoginBranding",
        "DescribeManagedLoginBranding",
        "DescribeManagedLoginBrandingByClient",
        "DeleteManagedLoginBranding",
    }:
        if client_id:
            cognitouserpools_ensure_managed_login_branding(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    if operation in {"UpdateTerms", "DescribeTerms", "DeleteTerms"}:
        cognitouserpools_ensure_terms(aws_bin, endpoint_url, region, env, user_pool_id)

    if operation in {
        "AdminGetUser",
        "AdminDeleteUser",
        "AdminDisableUser",
        "AdminEnableUser",
        "AdminResetUserPassword",
        "AdminUserGlobalSignOut",
        "AdminDeleteUserAttributes",
        "AdminUpdateUserAttributes",
        "AdminSetUserPassword",
        "AdminConfirmSignUp",
        "AdminListGroupsForUser",
        "AdminListDevices",
        "AdminGetDevice",
        "AdminForgetDevice",
        "AdminUpdateDeviceStatus",
        "AdminListUserAuthEvents",
        "AdminUpdateAuthEventFeedback",
        "AdminInitiateAuth",
        "AdminRespondToAuthChallenge",
        "AdminSetUserMFAPreference",
        "AdminSetUserSettings",
        "AdminLinkProviderForUser",
        "AdminDisableProviderForUser",
        "SetUICustomization",
        "GetUICustomization",
        "CreateManagedLoginBranding",
        "SetRiskConfiguration",
        "GetRiskConfiguration",
        "SetLogDeliveryConfiguration",
        "GetLogDeliveryConfiguration",
    }:
        if client_id:
            cognitouserpools_ensure_user(aws_bin, endpoint_url, region, env, user_pool_id, client_id)

    if operation in {
        "AssociateSoftwareToken",
        "StartWebAuthnRegistration",
        "UpdateAuthEventFeedback",
        "UpdateDeviceStatus",
        "UpdateUserAttributes",
        "GetDevice",
        "GetTokensFromRefreshToken",
        "GetUser",
        "GetUserAttributeVerificationCode",
        "GetUserAuthFactors",
        "ListDevices",
        "ListWebAuthnCredentials",
        "RevokeToken",
        "DeleteUser",
        "DeleteUserAttributes",
        "DeleteWebAuthnCredential",
        "ChangePassword",
        "CompleteWebAuthnRegistration",
        "ConfirmDevice",
        "ConfirmForgotPassword",
        "ConfirmSignUp",
        "ForgetDevice",
        "ForgotPassword",
        "GlobalSignOut",
        "InitiateAuth",
        "ResendConfirmationCode",
        "RespondToAuthChallenge",
        "SetUserMFAPreference",
        "SetUserSettings",
        "SignUp",
        "VerifySoftwareToken",
        "VerifyUserAttribute",
        "AdminListUserAuthEvents",
        "AdminUpdateAuthEventFeedback",
    }:
        if client_id:
            cognitouserpools_ensure_auth_tokens(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    if operation in {
        "GetDevice",
        "ForgetDevice",
        "UpdateDeviceStatus",
        "AdminGetDevice",
        "AdminForgetDevice",
        "AdminUpdateDeviceStatus",
    } and client_id:
        cognitouserpools_ensure_device(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    if operation in {"DeleteWebAuthnCredential"} and client_id:
        cognitouserpools_ensure_webauthn_credential(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    if operation in {"CompleteWebAuthnRegistration"} and client_id:
        cognitouserpools_prepare_complete_webauthn_registration(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    if operation in {"ConfirmForgotPassword"} and client_id:
        cognitouserpools_prepare_confirm_forgot_password(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    if operation in {"VerifyUserAttribute"} and client_id:
        cognitouserpools_prepare_verify_user_attribute(aws_bin, endpoint_url, region, env, user_pool_id, client_id)
    if operation in {"UpdateAuthEventFeedback", "AdminUpdateAuthEventFeedback"}:
        state = cognitouserpools_runtime_state(region)
        username = str(state.get("seed_username") or COGNITOUSERPOOLS_DEFAULT_USERNAME).strip() or COGNITOUSERPOOLS_DEFAULT_USERNAME
        listed = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "cognito-idp",
            "admin-list-user-auth-events",
            env,
            [
                "--user-pool-id",
                user_pool_id,
                "--username",
                username,
                "--max-results",
                "10",
            ],
        )
        if isinstance(listed, dict):
            cognitouserpools_record_runtime_payload(region, listed)

    if operation in {"RespondToAuthChallenge", "AdminRespondToAuthChallenge"} and client_id:
        state = cognitouserpools_runtime_state(region)
        username = str(state.get("seed_username") or COGNITOUSERPOOLS_DEFAULT_USERNAME).strip() or COGNITOUSERPOOLS_DEFAULT_USERNAME
        password = str(state.get("seed_password") or COGNITOUSERPOOLS_DEFAULT_PASSWORD).strip() or COGNITOUSERPOOLS_DEFAULT_PASSWORD
        run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "cognito-idp",
            "admin-set-user-password",
            env,
            [
                "--user-pool-id",
                user_pool_id,
                "--username",
                username,
                "--password",
                password,
            ],
        )
        if operation == "AdminRespondToAuthChallenge":
            _ = cognitouserpools_invoke_raw_json(
                operation="AdminInitiateAuth",
                endpoint_url=endpoint_url,
                region=region,
                env=env,
                payload={
                    "UserPoolId": user_pool_id,
                    "ClientId": client_id,
                    "AuthFlow": "ADMIN_USER_PASSWORD_AUTH",
                    "AuthParameters": {"USERNAME": username, "PASSWORD": password},
                },
            )
        else:
            _ = cognitouserpools_invoke_raw_json(
                operation="InitiateAuth",
                endpoint_url=endpoint_url,
                region=region,
                env=env,
                payload={
                    "ClientId": client_id,
                    "AuthFlow": "USER_PASSWORD_AUTH",
                    "AuthParameters": {"USERNAME": username, "PASSWORD": password},
                },
            )


def athena_list_named_query_ids(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    workgroup: str,
) -> list[str]:
    attempts: list[Sequence[str]] = []
    if workgroup:
        attempts.append(["--work-group", workgroup])
