def batch_seed_service_job_id_raw(
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    queue_name: str,
) -> str | None:
    endpoint = Endpoint(
        service="batch",
        cli_service="batch",
        operation="SubmitServiceJob",
        cli_operation="submit-service-job",
        source="raw-seed",
    )
    payload = {
        "jobName": BATCH_DEFAULT_SERVICE_JOB_NAME,
        "jobQueue": queue_name,
        "serviceJobType": "STATEFUL",
        "serviceRequestPayload": "{}",
        "schedulingPriority": 1,
        "shareIdentifier": "coverage",
        "tags": {"env": "coverage"},
    }
    status, body = invoke_raw_endpoint(endpoint, endpoint_url, region, env, payload)
    if status < 200 or status >= 300:
        return None
    try:
        data = json.loads(body) if body.strip() else {}
    except json.JSONDecodeError:
        return None
    if not isinstance(data, dict):
        return None
    value = data.get("jobId")
    if isinstance(value, str) and value.strip():
        RUNTIME_STATE.setdefault("batch", {})["service_job_id"] = value
        return value
    return None


