def acm_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("acm", {})
    defaults = {
        "region": region,
        "import_certificate_arn": ACM_DEFAULT_CERTIFICATE_ARN,
        "pending_email_certificate_arn": "",
        "pending_email_domain": ACM_DEFAULT_DOMAIN_NAME,
        "pending_email_validation_domain": ACM_DEFAULT_DOMAIN_NAME,
        "revoke_certificate_arn": "",
        "delete_certificate_arn": "",
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def acm_describe_certificate(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    certificate_arn: str,
) -> dict[str, object] | None:
    arn = str(certificate_arn).strip()
    if not arn:
        return None
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "acm",
        "describe-certificate",
        env,
        ["--certificate-arn", arn],
    )
    if not isinstance(data, dict):
        return None
    certificate = data.get("Certificate")
    if isinstance(certificate, dict):
        return certificate
    return None


def acm_request_certificate(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    *,
    domain_name: str,
    validation_method: str,
    idempotency_token: str,
    validation_domain: str,
) -> str:
    normalized_domain = str(domain_name).strip().lower() or ACM_DEFAULT_DOMAIN_NAME
    normalized_validation_domain = str(validation_domain).strip().lower() or normalized_domain
    normalized_method = str(validation_method).strip().upper() or "DNS"
    token = re.sub(r"[^a-zA-Z0-9]", "", str(idempotency_token))[:32] or "stackyardtoken"
    payload = {
        "DomainName": normalized_domain,
        "IdempotencyToken": token,
        "ValidationMethod": normalized_method,
        "DomainValidationOptions": [
            {
                "DomainName": normalized_domain,
                "ValidationDomain": normalized_validation_domain,
            }
        ],
        "Tags": [{"Key": "env", "Value": "coverage"}],
    }
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "acm",
        "request-certificate",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(data, dict):
        arn = data.get("CertificateArn")
        if isinstance(arn, str) and arn.strip():
            return arn.strip()
    return ""


def acm_ensure_imported_certificate(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = acm_runtime_state(region)
    arn = str(state.get("import_certificate_arn") or ACM_DEFAULT_CERTIFICATE_ARN).strip() or ACM_DEFAULT_CERTIFICATE_ARN
    cert = acm_describe_certificate(aws_bin, endpoint_url, region, env, arn)
    if isinstance(cert, dict) and str(cert.get("Type", "")).strip().upper() == "IMPORTED":
        return arn

    payload = {
        "CertificateArn": arn,
        "Certificate": "c3RhY2t5YXJk",
        "PrivateKey": "c3RhY2t5YXJk",
        "CertificateChain": "c3RhY2t5YXJk",
        "Tags": [{"Key": "env", "Value": "coverage"}],
    }
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "acm",
        "import-certificate",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(data, dict):
        response_arn = data.get("CertificateArn")
        if isinstance(response_arn, str) and response_arn.strip():
            arn = response_arn.strip()

    state["import_certificate_arn"] = arn
    return arn


def acm_ensure_pending_email_certificate(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> tuple[str, str, str]:
    state = acm_runtime_state(region)
    candidates = [
        str(state.get("pending_email_certificate_arn") or "").strip(),
    ]
    for arn in candidates:
        if not arn:
            continue
        cert = acm_describe_certificate(aws_bin, endpoint_url, region, env, arn)
        if not isinstance(cert, dict):
            continue
        status = str(cert.get("Status") or "").strip().upper()
        method = str(cert.get("ValidationMethod") or "").strip().upper()
        if status != "PENDING_VALIDATION" or method != "EMAIL":
            continue
        domain_name = str(cert.get("DomainName") or state.get("pending_email_domain") or ACM_DEFAULT_DOMAIN_NAME).strip().lower()
        validation_domain = str(state.get("pending_email_validation_domain") or domain_name).strip().lower() or domain_name
        options = cert.get("DomainValidationOptions")
        if isinstance(options, list):
            for item in options:
                if not isinstance(item, dict):
                    continue
                value = str(item.get("ValidationDomain") or "").strip().lower()
                if value:
                    validation_domain = value
                    break
        state["pending_email_certificate_arn"] = arn
        state["pending_email_domain"] = domain_name
        state["pending_email_validation_domain"] = validation_domain
        return arn, domain_name, validation_domain

    unique = str(int(time.time() * 1000) % 1000000).zfill(6)
    domain_name = f"pending-{unique}.stackyard.example.com"
    validation_domain = domain_name
    arn = acm_request_certificate(
        aws_bin,
        endpoint_url,
        region,
        env,
        domain_name=domain_name,
        validation_method="EMAIL",
        idempotency_token=f"pending{unique}",
        validation_domain=validation_domain,
    )
    if not arn:
        arn = str(state.get("pending_email_certificate_arn") or ACM_DEFAULT_CERTIFICATE_ARN).strip() or ACM_DEFAULT_CERTIFICATE_ARN
    state["pending_email_certificate_arn"] = arn
    state["pending_email_domain"] = domain_name
    state["pending_email_validation_domain"] = validation_domain
    return arn, domain_name, validation_domain


def acm_ensure_revoke_certificate(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = acm_runtime_state(region)
    arn = str(state.get("revoke_certificate_arn") or "").strip()
    if arn:
        cert = acm_describe_certificate(aws_bin, endpoint_url, region, env, arn)
        if isinstance(cert, dict) and str(cert.get("Status") or "").strip().upper() != "REVOKED":
            return arn

    unique = str(int(time.time() * 1000) % 1000000).zfill(6)
    domain_name = f"revoke-{unique}.stackyard.example.com"
    arn = acm_request_certificate(
        aws_bin,
        endpoint_url,
        region,
        env,
        domain_name=domain_name,
        validation_method="DNS",
        idempotency_token=f"revoke{unique}",
        validation_domain=domain_name,
    )
    if not arn:
        arn = acm_ensure_imported_certificate(aws_bin, endpoint_url, region, env)
    state["revoke_certificate_arn"] = arn
    state["delete_certificate_arn"] = arn
    return arn


def acm_ensure_delete_certificate(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = acm_runtime_state(region)
    arn = str(state.get("delete_certificate_arn") or state.get("revoke_certificate_arn") or "").strip()
    if arn:
        cert = acm_describe_certificate(aws_bin, endpoint_url, region, env, arn)
        if isinstance(cert, dict):
            return arn

    unique = str(int(time.time() * 1000) % 1000000).zfill(6)
    domain_name = f"delete-{unique}.stackyard.example.com"
    arn = acm_request_certificate(
        aws_bin,
        endpoint_url,
        region,
        env,
        domain_name=domain_name,
        validation_method="DNS",
        idempotency_token=f"delete{unique}",
        validation_domain=domain_name,
    )
    if not arn:
        arn = acm_ensure_imported_certificate(aws_bin, endpoint_url, region, env)
    state["delete_certificate_arn"] = arn
    return arn


def privateca_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("privateca", {})
    defaults = {
        "region": region,
        "certificate_authority_arn": PRIVATECA_DEFAULT_CA_ARN,
        "certificate_arn": PRIVATECA_DEFAULT_CERTIFICATE_ARN,
        "serial": PRIVATECA_DEFAULT_SERIAL,
        "template_arn": PRIVATECA_DEFAULT_TEMPLATE_ARN,
        "audit_report_id": PRIVATECA_DEFAULT_AUDIT_REPORT_ID,
        "s3_key": PRIVATECA_DEFAULT_S3_KEY,
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def privateca_record_runtime_payload(region: str, payload: dict[str, object]) -> None:
    if not isinstance(payload, dict):
        return
    state = privateca_runtime_state(region)

    def _capture_ca_arn(value: object) -> None:
        if isinstance(value, str) and value.strip():
            state["certificate_authority_arn"] = value.strip()

    def _capture_cert_arn(value: object) -> None:
        if isinstance(value, str) and value.strip():
            state["certificate_arn"] = value.strip()

    _capture_ca_arn(payload.get("CertificateAuthorityArn"))
    _capture_cert_arn(payload.get("CertificateArn"))
    audit_report_id = payload.get("AuditReportId")
    if isinstance(audit_report_id, str) and audit_report_id.strip():
        state["audit_report_id"] = audit_report_id.strip()
    s3_key = payload.get("S3Key")
    if isinstance(s3_key, str) and s3_key.strip():
        state["s3_key"] = s3_key.strip()

    certificate_authority = payload.get("CertificateAuthority")
    if isinstance(certificate_authority, dict):
        _capture_ca_arn(certificate_authority.get("Arn"))

    certificate_authorities = payload.get("CertificateAuthorities")
    if isinstance(certificate_authorities, list):
        for item in certificate_authorities:
            if not isinstance(item, dict):
                continue
            _capture_ca_arn(item.get("Arn"))
            break

    certificate = payload.get("Certificate")
    if isinstance(certificate, dict):
        _capture_cert_arn(certificate.get("CertificateArn"))
        _capture_ca_arn(certificate.get("CertificateAuthorityArn"))


def privateca_ensure_certificate_authority_arn(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = privateca_runtime_state(region)
    arn = str(state.get("certificate_authority_arn") or PRIVATECA_DEFAULT_CA_ARN).strip() or PRIVATECA_DEFAULT_CA_ARN
    described = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "acm-pca",
        "describe-certificate-authority",
        env,
        ["--certificate-authority-arn", arn],
    )
    if isinstance(described, dict):
        privateca_record_runtime_payload(region, described)
        current = str(state.get("certificate_authority_arn") or arn).strip()
        if current:
            return current

    payload = {
        "CertificateAuthorityConfiguration": {
            "KeyAlgorithm": "RSA_2048",
            "SigningAlgorithm": "SHA256WITHRSA",
            "Subject": {
                "Country": "US",
                "Organization": "Stackyard",
                "OrganizationalUnit": "Engineering",
                "State": "WA",
                "Locality": "Seattle",
                "CommonName": "stackyard-privateca",
            },
        },
        "CertificateAuthorityType": "ROOT",
        "IdempotencyToken": PRIVATECA_DEFAULT_IDEMPOTENCY_TOKEN,
        "UsageMode": "GENERAL_PURPOSE",
        "Tags": [{"Key": "env", "Value": "coverage"}],
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "acm-pca",
        "create-certificate-authority",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(created, dict):
        privateca_record_runtime_payload(region, created)

    return str(state.get("certificate_authority_arn") or arn).strip() or arn


def privateca_ensure_audit_report_id(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = privateca_runtime_state(region)
    ca_arn = privateca_ensure_certificate_authority_arn(aws_bin, endpoint_url, region, env)
    report_id = str(state.get("audit_report_id") or PRIVATECA_DEFAULT_AUDIT_REPORT_ID).strip() or PRIVATECA_DEFAULT_AUDIT_REPORT_ID
    s3_key = str(state.get("s3_key") or PRIVATECA_DEFAULT_S3_KEY).strip() or PRIVATECA_DEFAULT_S3_KEY

    described = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "acm-pca",
        "describe-certificate-authority-audit-report",
        env,
        [
            "--certificate-authority-arn",
            ca_arn,
            "--audit-report-id",
            report_id,
        ],
    )
    if isinstance(described, dict):
        privateca_record_runtime_payload(region, described)
        current = str(state.get("audit_report_id") or report_id).strip()
        if current:
            return current

    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "acm-pca",
        "create-certificate-authority-audit-report",
        env,
        [
            "--certificate-authority-arn",
            ca_arn,
            "--s3-bucket-name",
            PRIVATECA_DEFAULT_S3_BUCKET_NAME,
            "--audit-report-response-format",
            "JSON",
        ],
    )
    if isinstance(created, dict):
        privateca_record_runtime_payload(region, created)
        report_id = str(state.get("audit_report_id") or report_id).strip() or report_id
        s3_key = str(state.get("s3_key") or s3_key).strip() or s3_key

    state["audit_report_id"] = report_id
    state["s3_key"] = s3_key
    return report_id


def secretsmanager_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("secretsmanager", {})
    defaults = {
        "region": region,
        "secret_name": f"{SECRETSMANAGER_DEFAULT_SECRET_NAME}-{region}-coverage",
        "secret_arn": SECRETSMANAGER_DEFAULT_SECRET_ARN,
        "secret_id": SECRETSMANAGER_DEFAULT_SECRET_ARN,
        "current_version_id": "",
        "previous_version_id": "",
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def secretsmanager_record_runtime_payload(region: str, payload: object) -> None:
    if not isinstance(payload, dict):
        return
    state = secretsmanager_runtime_state(region)

    def _capture_secret_id(value: object) -> None:
        if isinstance(value, str) and value.strip():
            cleaned = value.strip()
            state["secret_arn"] = cleaned
            state["secret_id"] = cleaned

    def _capture_secret_name(value: object) -> None:
        if isinstance(value, str) and value.strip():
            state["secret_name"] = value.strip()

    def _capture_version(value: object, stage_hint: str | None = None) -> None:
        if not isinstance(value, str) or not value.strip():
            return
        cleaned = value.strip()
        if stage_hint == "AWSPREVIOUS":
            state["previous_version_id"] = cleaned
            return
        state["current_version_id"] = cleaned

    _capture_secret_id(payload.get("ARN"))
    _capture_secret_name(payload.get("Name"))
    _capture_version(payload.get("VersionId"))

    secret_list = payload.get("SecretList")
    if isinstance(secret_list, list):
        for item in secret_list:
            if not isinstance(item, dict):
                continue
            _capture_secret_id(item.get("ARN"))
            _capture_secret_name(item.get("Name"))
            break

    secret_values = payload.get("SecretValues")
    if isinstance(secret_values, list):
        for item in secret_values:
            if not isinstance(item, dict):
                continue
            _capture_secret_id(item.get("ARN"))
            _capture_secret_name(item.get("Name"))
            _capture_version(item.get("VersionId"))
            stages = item.get("VersionStages")
            if isinstance(stages, list):
                stages_norm = {str(stage).strip().upper() for stage in stages if isinstance(stage, str)}
                if "AWSPREVIOUS" in stages_norm:
                    _capture_version(item.get("VersionId"), "AWSPREVIOUS")
            break

    versions = payload.get("Versions")
    if isinstance(versions, list):
        for item in versions:
            if not isinstance(item, dict):
                continue
            version_id = item.get("VersionId")
            stages = item.get("VersionStages")
            if not isinstance(stages, list):
                continue
            stages_norm = {str(stage).strip().upper() for stage in stages if isinstance(stage, str)}
            if "AWSCURRENT" in stages_norm:
                _capture_version(version_id, "AWSCURRENT")
            if "AWSPREVIOUS" in stages_norm:
                _capture_version(version_id, "AWSPREVIOUS")

    version_map = payload.get("VersionIdsToStages")
    if isinstance(version_map, dict):
        for version_id, stages in version_map.items():
            if not isinstance(version_id, str):
                continue
            if isinstance(stages, list):
                stages_norm = {str(stage).strip().upper() for stage in stages if isinstance(stage, str)}
                if "AWSCURRENT" in stages_norm:
                    _capture_version(version_id, "AWSCURRENT")
                if "AWSPREVIOUS" in stages_norm:
                    _capture_version(version_id, "AWSPREVIOUS")


def secretsmanager_operation_state_key(operation: str) -> str:
    if operation == "RestoreSecret":
        return "restore"
    if operation == "CancelRotateSecret":
        return "cancelrotate"
    if operation in {"ReplicateSecretToRegions", "RemoveRegionsFromReplication", "StopReplicationToReplica"}:
        return "replication"
    if operation in {"PutResourcePolicy", "GetResourcePolicy", "DeleteResourcePolicy", "ValidateResourcePolicy"}:
        return "policy"
    if operation == "UpdateSecretVersionStage":
        return "versionstage"
    if operation == "DeleteSecret":
        return "delete"
    if operation in {"TagResource", "UntagResource"}:
        return "tags"
    return "default"


def secretsmanager_ensure_secret_for_key(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    key: str,
) -> str:
    state = secretsmanager_runtime_state(region)
    arn_key = f"{key}_secret_arn"
    name_key = f"{key}_secret_name"
    token_key = f"{key}_create_token"

    existing_arn = str(state.get(arn_key) or "").strip()
    if existing_arn:
        described = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "secretsmanager",
            "describe-secret",
            env,
            ["--secret-id", existing_arn],
        )
        if isinstance(described, dict):
            secretsmanager_record_runtime_payload(region, described)
            return existing_arn

    unique_suffix = str(int(time.time() * 1000) % 1000000).zfill(6)
    secret_name = str(state.get(name_key) or f"{SECRETSMANAGER_DEFAULT_SECRET_NAME}-{key}-{unique_suffix}").strip()
    create_token = str(state.get(token_key) or f"{SECRETSMANAGER_DEFAULT_CLIENT_REQUEST_TOKEN}-{key}-{unique_suffix}").strip()

    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "secretsmanager",
        "create-secret",
        env,
        [
            "--name",
            secret_name,
            "--secret-string",
            '{"username":"stackyard","password":"stackyard"}',
            "--client-request-token",
            create_token,
            "--description",
            "coverage secret",
        ],
    )
    if isinstance(created, dict):
        secretsmanager_record_runtime_payload(region, created)
        created_arn = str(created.get("ARN") or state.get("secret_arn") or "").strip()
        if created_arn:
            state[arn_key] = created_arn
            state[name_key] = secret_name
            state[token_key] = create_token
            state["secret_arn"] = created_arn
            state["secret_id"] = created_arn
            state["secret_name"] = secret_name
            return created_arn

    listed = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "secretsmanager",
        "list-secrets",
        env,
        ["--max-results", "100"],
    )
    if isinstance(listed, dict):
        secretsmanager_record_runtime_payload(region, listed)
        items = listed.get("SecretList")
        if isinstance(items, list):
            for item in items:
                if not isinstance(item, dict):
                    continue
                item_name = item.get("Name")
                item_arn = item.get("ARN")
                if isinstance(item_name, str) and item_name.strip() == secret_name and isinstance(item_arn, str) and item_arn.strip():
                    state[arn_key] = item_arn.strip()
                    state[name_key] = secret_name
                    state["secret_arn"] = item_arn.strip()
                    state["secret_id"] = item_arn.strip()
                    return item_arn.strip()

    fallback = str(state.get("secret_arn") or state.get("secret_id") or SECRETSMANAGER_DEFAULT_SECRET_ARN).strip()
    if fallback:
        state[arn_key] = fallback
    return fallback or SECRETSMANAGER_DEFAULT_SECRET_ARN


def secretsmanager_prepare_operation_state(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    operation: str,
) -> str:
    state = secretsmanager_runtime_state(region)
    if operation in {"CreateSecret", "ListSecrets", "GetRandomPassword"}:
        return str(state.get("secret_id") or state.get("secret_arn") or SECRETSMANAGER_DEFAULT_SECRET_ARN)

    key = secretsmanager_operation_state_key(operation)
    secret_arn = secretsmanager_ensure_secret_for_key(aws_bin, endpoint_url, region, env, key)
    if not secret_arn:
        return SECRETSMANAGER_DEFAULT_SECRET_ARN

    if operation in {"GetResourcePolicy", "DeleteResourcePolicy"}:
        seeded = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "secretsmanager",
            "put-resource-policy",
            env,
            [
                "--secret-id",
                secret_arn,
                "--resource-policy",
                SECRETSMANAGER_DEFAULT_RESOURCE_POLICY,
            ],
        )
        if isinstance(seeded, dict):
            secretsmanager_record_runtime_payload(region, seeded)

    if operation == "RestoreSecret":
        run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "secretsmanager",
            "delete-secret",
            env,
            ["--secret-id", secret_arn, "--recovery-window-in-days", "7"],
        )

    if operation == "CancelRotateSecret":
        seeded = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "secretsmanager",
            "rotate-secret",
            env,
            [
                "--secret-id",
                secret_arn,
                "--rotation-lambda-arn",
                SECRETSMANAGER_DEFAULT_ROTATION_LAMBDA_ARN,
                "--rotate-immediately",
                "--rotation-rules",
                "AutomaticallyAfterDays=30",
            ],
        )
        if isinstance(seeded, dict):
            secretsmanager_record_runtime_payload(region, seeded)

    if operation in {"RemoveRegionsFromReplication", "StopReplicationToReplica"}:
        seed_payload = {
            "SecretId": secret_arn,
            "AddReplicaRegions": [{"Region": "us-west-2"}],
            "ForceOverwriteReplicaSecret": True,
        }
        seeded = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "secretsmanager",
            "replicate-secret-to-regions",
            env,
            ["--cli-input-json", json.dumps(seed_payload, separators=(",", ":"))],
        )
        if isinstance(seeded, dict):
            secretsmanager_record_runtime_payload(region, seeded)

    if operation == "UpdateSecretVersionStage":
        token = f"{SECRETSMANAGER_DEFAULT_CLIENT_REQUEST_TOKEN}-versionstage-{int(time.time() * 1000) % 1000000:06d}"
        seeded = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "secretsmanager",
            "put-secret-value",
            env,
            [
                "--secret-id",
                secret_arn,
                "--secret-string",
                '{"username":"stackyard","password":"stage"}',
                "--client-request-token",
                token,
            ],
        )
        if isinstance(seeded, dict):
            secretsmanager_record_runtime_payload(region, seeded)

    state["secret_arn"] = secret_arn
    state["secret_id"] = secret_arn
    return secret_arn


def cloudhsm_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("cloudhsm", {})
    defaults = {
        "region": region,
        "cluster_id": CLOUDHSM_DEFAULT_CLUSTER_ID,
        "cluster_arn": CLOUDHSM_DEFAULT_CLUSTER_ARN,
        "backup_id": CLOUDHSM_DEFAULT_BACKUP_ID,
        "backup_arn": CLOUDHSM_DEFAULT_BACKUP_ARN,
        "hsm_id": CLOUDHSM_DEFAULT_HSM_ID,
        "resource_id": CLOUDHSM_DEFAULT_CLUSTER_ID,
        "resource_arn": CLOUDHSM_DEFAULT_CLUSTER_ARN,
        "policy": CLOUDHSM_DEFAULT_POLICY,
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def cloudhsm_cluster_arn(region: str, cluster_id: str) -> str:
    return f"arn:aws:cloudhsm:{region}:123456789012:cluster/{cluster_id}"


def cloudhsm_backup_arn(region: str, backup_id: str) -> str:
    return f"arn:aws:cloudhsm:{region}:123456789012:backup/{backup_id}"


def cloudhsm_record_runtime_payload(region: str, payload: dict[str, object]) -> None:
    if not isinstance(payload, dict):
        return
    state = cloudhsm_runtime_state(region)

    def _save_cluster(cluster_obj: object) -> None:
        if not isinstance(cluster_obj, dict):
            return
        cluster_id = cluster_obj.get("ClusterId")
        if isinstance(cluster_id, str) and cluster_id.strip():
            cid = cluster_id.strip()
            state["cluster_id"] = cid
            state["cluster_arn"] = cloudhsm_cluster_arn(region, cid)
            state["resource_id"] = cid
            state["resource_arn"] = str(state["cluster_arn"])
        hsms = cluster_obj.get("Hsms")
        if isinstance(hsms, list):
            for item in hsms:
                if not isinstance(item, dict):
                    continue
                hsm_id = item.get("HsmId")
                if isinstance(hsm_id, str) and hsm_id.strip():
                    state["hsm_id"] = hsm_id.strip()
                    break

    def _save_backup(backup_obj: object) -> None:
        if not isinstance(backup_obj, dict):
            return
        backup_id = backup_obj.get("BackupId")
        if isinstance(backup_id, str) and backup_id.strip():
            bid = backup_id.strip()
            state["backup_id"] = bid
            state["backup_arn"] = cloudhsm_backup_arn(region, bid)

    _save_cluster(payload.get("Cluster"))
    _save_backup(payload.get("Backup"))
    _save_backup(payload.get("DestinationBackup"))

    clusters = payload.get("Clusters")
    if isinstance(clusters, list) and clusters:
        _save_cluster(clusters[0])
    backups = payload.get("Backups")
    if isinstance(backups, list) and backups:
        _save_backup(backups[0])

    hsm_obj = payload.get("Hsm")
    if isinstance(hsm_obj, dict):
        hsm_id = hsm_obj.get("HsmId")
        if isinstance(hsm_id, str) and hsm_id.strip():
            state["hsm_id"] = hsm_id.strip()
    hsm_id = payload.get("HsmId")
    if isinstance(hsm_id, str) and hsm_id.strip():
        state["hsm_id"] = hsm_id.strip()

    resource_arn = payload.get("ResourceArn")
    if isinstance(resource_arn, str) and resource_arn.strip():
        state["resource_arn"] = resource_arn.strip()
    policy = payload.get("Policy")
    if isinstance(policy, str):
        state["policy"] = policy


def cloudhsm_ensure_cluster(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> tuple[str, str]:
    state = cloudhsm_runtime_state(region)
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cloudhsmv2",
        "describe-clusters",
        env,
        ["--max-results", "10"],
    )
    if isinstance(data, dict):
        cloudhsm_record_runtime_payload(region, data)
    cluster_id = str(state.get("cluster_id") or CLOUDHSM_DEFAULT_CLUSTER_ID).strip() or CLOUDHSM_DEFAULT_CLUSTER_ID
    cluster_arn = str(state.get("cluster_arn") or cloudhsm_cluster_arn(region, cluster_id))
    if isinstance(data, dict):
        clusters = data.get("Clusters")
        if isinstance(clusters, list):
            for item in clusters:
                if not isinstance(item, dict):
                    continue
                item_cluster_id = item.get("ClusterId")
                if isinstance(item_cluster_id, str) and item_cluster_id.strip():
                    cluster_id = item_cluster_id.strip()
                    cluster_arn = cloudhsm_cluster_arn(region, cluster_id)
                    state["cluster_id"] = cluster_id
                    state["cluster_arn"] = cluster_arn
                    state["resource_id"] = cluster_id
                    state["resource_arn"] = cluster_arn
                    return cluster_id, cluster_arn

    unique = str(int(time.time() * 1000) % 1000000).zfill(6)
    payload = {
        "HsmType": "hsm1.medium",
        "SubnetIds": [CLOUDHSM_DEFAULT_SUBNET_ID],
        "TagList": [{"Key": "env", "Value": f"coverage-{unique}"}],
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cloudhsmv2",
        "create-cluster",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(created, dict):
        cloudhsm_record_runtime_payload(region, created)
    cluster_id = str(state.get("cluster_id") or cluster_id).strip() or cluster_id
    cluster_arn = str(state.get("cluster_arn") or cluster_arn).strip() or cluster_arn
    state["resource_id"] = cluster_id
    state["resource_arn"] = cluster_arn
    return cluster_id, cluster_arn


def cloudhsm_ensure_backup(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> tuple[str, str]:
    state = cloudhsm_runtime_state(region)
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cloudhsmv2",
        "describe-backups",
        env,
        ["--max-results", "10"],
    )
    if isinstance(data, dict):
        cloudhsm_record_runtime_payload(region, data)
        backups = data.get("Backups")
        if isinstance(backups, list):
            for item in backups:
                if not isinstance(item, dict):
                    continue
                backup_id = item.get("BackupId")
                if isinstance(backup_id, str) and backup_id.strip():
                    bid = backup_id.strip()
                    state["backup_id"] = bid
                    state["backup_arn"] = cloudhsm_backup_arn(region, bid)
                    return bid, str(state["backup_arn"])

    cloudhsm_ensure_cluster(aws_bin, endpoint_url, region, env)
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cloudhsmv2",
        "describe-backups",
        env,
        ["--max-results", "10"],
    )
    if isinstance(data, dict):
        cloudhsm_record_runtime_payload(region, data)
        backups = data.get("Backups")
        if isinstance(backups, list):
            for item in backups:
                if not isinstance(item, dict):
                    continue
                backup_id = item.get("BackupId")
                if isinstance(backup_id, str) and backup_id.strip():
                    bid = backup_id.strip()
                    state["backup_id"] = bid
                    state["backup_arn"] = cloudhsm_backup_arn(region, bid)
                    return bid, str(state["backup_arn"])

    backup_id = str(state.get("backup_id") or CLOUDHSM_DEFAULT_BACKUP_ID).strip() or CLOUDHSM_DEFAULT_BACKUP_ID
    backup_arn = str(state.get("backup_arn") or cloudhsm_backup_arn(region, backup_id)).strip()
    return backup_id, backup_arn


def cloudhsm_ensure_hsm(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = cloudhsm_runtime_state(region)
    cluster_id, _ = cloudhsm_ensure_cluster(aws_bin, endpoint_url, region, env)
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cloudhsmv2",
        "describe-clusters",
        env,
        ["--max-results", "10"],
    )
    if isinstance(data, dict):
        cloudhsm_record_runtime_payload(region, data)
        clusters = data.get("Clusters")
        if isinstance(clusters, list):
            for item in clusters:
                if not isinstance(item, dict):
                    continue
                cid = item.get("ClusterId")
                if not isinstance(cid, str) or cid.strip() != cluster_id:
                    continue
                hsms = item.get("Hsms")
                if isinstance(hsms, list):
                    for hsm_item in hsms:
                        if not isinstance(hsm_item, dict):
                            continue
                        hsm_id = hsm_item.get("HsmId")
                        if isinstance(hsm_id, str) and hsm_id.strip():
                            state["hsm_id"] = hsm_id.strip()
                            return hsm_id.strip()

    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "cloudhsmv2",
        "create-hsm",
        env,
        [
            "--cluster-id",
            cluster_id,
            "--availability-zone",
            "us-east-1a",
        ],
    )
    if isinstance(created, dict):
        cloudhsm_record_runtime_payload(region, created)
    return str(state.get("hsm_id") or CLOUDHSM_DEFAULT_HSM_ID).strip() or CLOUDHSM_DEFAULT_HSM_ID


def kms_unique_suffix() -> str:
    return str(int(time.time() * 1000) % 1000000).zfill(6)


def kms_key_arn(region: str, key_id: str) -> str:
    return f"arn:aws:kms:{region}:123456789012:key/{key_id}"


def kms_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("kms", {})
    defaults: dict[str, object] = {
        "region": region,
        "encrypt_key_id": "",
        "encrypt_key_arn": "",
        "secondary_key_id": "",
        "secondary_key_arn": "",
        "sign_key_id": "",
        "sign_key_arn": "",
        "mac_key_id": "",
        "mac_key_arn": "",
        "agreement_key_id": "",
        "agreement_key_arn": "",
        "alias_name": KMS_DEFAULT_ALIAS_NAME,
        "grant_id": "",
        "grant_token": "",
        "grantee_principal": KMS_DEFAULT_GRANTEE_PRINCIPAL,
        "retiring_principal": KMS_DEFAULT_RETIRING_PRINCIPAL,
        "ciphertext_blob": "",
        "signature": "",
        "signing_algorithm": "",
        "mac": "",
        "mac_algorithm": "",
        "plaintext_b64": KMS_DEFAULT_PLAINTEXT_B64,
        "sign_message_b64": KMS_DEFAULT_SIGN_MESSAGE_B64,
        "mac_message_b64": KMS_DEFAULT_MAC_MESSAGE_B64,
        "peer_public_key_b64": KMS_DEFAULT_PEER_PUBLIC_KEY_B64,
        "import_token": "",
        "wrapping_algorithm": KMS_DEFAULT_WRAPPING_ALGORITHM,
        "wrapping_key_spec": KMS_DEFAULT_WRAPPING_KEY_SPEC,
        "policy_name": KMS_DEFAULT_POLICY_NAME,
        "policy_document": KMS_DEFAULT_POLICY_DOCUMENT,
        "custom_key_store_id": "",
        "custom_key_store_name": "",
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def kms_record_runtime_payload(region: str, payload: object) -> None:
    if not isinstance(payload, dict):
        return
    state = kms_runtime_state(region)

    def _save_key(meta_obj: object) -> None:
        if not isinstance(meta_obj, dict):
            return
        key_id = meta_obj.get("KeyId")
        arn = meta_obj.get("Arn")
        usage = str(meta_obj.get("KeyUsage") or "").strip()
        key_id_str = key_id.strip() if isinstance(key_id, str) and key_id.strip() else ""
        arn_str = arn.strip() if isinstance(arn, str) and arn.strip() else ""
        if key_id_str and not arn_str:
            arn_str = kms_key_arn(region, key_id_str)
        if not key_id_str:
            return
        if usage == "SIGN_VERIFY":
            state["sign_key_id"] = key_id_str
            state["sign_key_arn"] = arn_str
            return
        if usage == "GENERATE_VERIFY_MAC":
            state["mac_key_id"] = key_id_str
            state["mac_key_arn"] = arn_str
            return
        if usage == "KEY_AGREEMENT":
            state["agreement_key_id"] = key_id_str
            state["agreement_key_arn"] = arn_str
            return
        if not str(state.get("encrypt_key_id") or "").strip():
            state["encrypt_key_id"] = key_id_str
            state["encrypt_key_arn"] = arn_str

    _save_key(payload.get("KeyMetadata"))
    _save_key(payload.get("ReplicaKeyMetadata"))

    key_id = payload.get("KeyId")
    if isinstance(key_id, str) and key_id.strip() and key_id.startswith("arn:aws:kms:"):
        state["encrypt_key_arn"] = key_id.strip()
    elif isinstance(key_id, str) and key_id.strip():
        state["encrypt_key_id"] = key_id.strip()

    import_token = payload.get("ImportToken")
    if isinstance(import_token, str) and import_token.strip():
        state["import_token"] = import_token.strip()
    ciphertext_blob = payload.get("CiphertextBlob")
    if isinstance(ciphertext_blob, str) and ciphertext_blob.strip():
        state["ciphertext_blob"] = ciphertext_blob.strip()
    signature = payload.get("Signature")
    if isinstance(signature, str) and signature.strip():
        state["signature"] = signature.strip()
    signing_algorithm = payload.get("SigningAlgorithm")
    if isinstance(signing_algorithm, str) and signing_algorithm.strip():
        state["signing_algorithm"] = signing_algorithm.strip()
    mac = payload.get("Mac")
    if isinstance(mac, str) and mac.strip():
        state["mac"] = mac.strip()
    mac_algorithm = payload.get("MacAlgorithm")
    if isinstance(mac_algorithm, str) and mac_algorithm.strip():
        state["mac_algorithm"] = mac_algorithm.strip()
    alias_name = payload.get("AliasName")
    if isinstance(alias_name, str) and alias_name.strip():
        state["alias_name"] = alias_name.strip()
    grant_id = payload.get("GrantId")
    if isinstance(grant_id, str) and grant_id.strip():
        state["grant_id"] = grant_id.strip()
    grant_token = payload.get("GrantToken")
    if isinstance(grant_token, str) and grant_token.strip():
        state["grant_token"] = grant_token.strip()
    custom_store_id = payload.get("CustomKeyStoreId")
    if isinstance(custom_store_id, str) and custom_store_id.strip():
        state["custom_key_store_id"] = custom_store_id.strip()

    aliases = payload.get("Aliases")
    if isinstance(aliases, list):
        for item in aliases:
            if not isinstance(item, dict):
                continue
            alias = item.get("AliasName")
            if isinstance(alias, str) and alias.strip() and alias.startswith("alias/"):
                state["alias_name"] = alias.strip()
                break

    grants = payload.get("Grants")
    if isinstance(grants, list):
        for item in grants:
            if not isinstance(item, dict):
                continue
            gid = item.get("GrantId")
            if isinstance(gid, str) and gid.strip():
                state["grant_id"] = gid.strip()
                break

    custom_stores = payload.get("CustomKeyStores")
    if isinstance(custom_stores, list):
        for item in custom_stores:
            if not isinstance(item, dict):
                continue
            sid = item.get("CustomKeyStoreId")
            if isinstance(sid, str) and sid.strip():
                state["custom_key_store_id"] = sid.strip()
                name = item.get("CustomKeyStoreName")
                if isinstance(name, str) and name.strip():
                    state["custom_key_store_name"] = name.strip()
                break

    keys = payload.get("Keys")
    if isinstance(keys, list):
        for item in keys:
            if not isinstance(item, dict):
                continue
            kid = item.get("KeyId")
            if isinstance(kid, str) and kid.strip():
                state["encrypt_key_id"] = kid.strip()
                karn = item.get("KeyArn")
                if isinstance(karn, str) and karn.strip():
                    state["encrypt_key_arn"] = karn.strip()
                break


def kms_ensure_key(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    state_id_key: str,
    state_arn_key: str,
    key_usage: str,
    key_spec: str,
    force_new: bool = False,
) -> tuple[str, str]:
    state = kms_runtime_state(region)
    existing_id = str(state.get(state_id_key) or "").strip()
    existing_arn = str(state.get(state_arn_key) or "").strip()
    if existing_id and not force_new:
        described = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "kms",
            "describe-key",
            env,
            ["--key-id", existing_id],
        )
        if isinstance(described, dict):
            kms_record_runtime_payload(region, described)
            existing_id = str(state.get(state_id_key) or existing_id).strip()
            existing_arn = str(state.get(state_arn_key) or existing_arn).strip()
            if existing_id:
                if not existing_arn:
                    existing_arn = kms_key_arn(region, existing_id)
                return existing_id, existing_arn

    payload = {
        "Description": f"stackyard-kms-{key_usage.lower()}-{kms_unique_suffix()}",
        "KeyUsage": key_usage,
        "KeySpec": key_spec,
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "create-key",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(created, dict):
        kms_record_runtime_payload(region, created)
        meta = created.get("KeyMetadata")
        if isinstance(meta, dict):
            key_id = meta.get("KeyId")
            arn = meta.get("Arn")
            if isinstance(key_id, str) and key_id.strip():
                state[state_id_key] = key_id.strip()
                if isinstance(arn, str) and arn.strip():
                    state[state_arn_key] = arn.strip()
                else:
                    state[state_arn_key] = kms_key_arn(region, key_id.strip())

    key_id = str(state.get(state_id_key) or "").strip()
    key_arn = str(state.get(state_arn_key) or "").strip()
    if not key_arn and key_id:
        key_arn = kms_key_arn(region, key_id)
        state[state_arn_key] = key_arn
    return key_id, key_arn


def kms_ensure_encrypt_key(aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], force_new: bool = False) -> tuple[str, str]:
    return kms_ensure_key(
        aws_bin,
        endpoint_url,
        region,
        env,
        "encrypt_key_id",
        "encrypt_key_arn",
        "ENCRYPT_DECRYPT",
        "SYMMETRIC_DEFAULT",
        force_new=force_new,
    )


