def kms_ensure_alias(aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], force_new: bool = False) -> tuple[str, str]:
    state = kms_runtime_state(region)
    key_id, _ = kms_ensure_encrypt_key(aws_bin, endpoint_url, region, env)
    alias_name = str(state.get("alias_name") or KMS_DEFAULT_ALIAS_NAME).strip() or KMS_DEFAULT_ALIAS_NAME
    if force_new or not alias_name.startswith("alias/"):
        alias_name = f"alias/stackyard-coverage-{kms_unique_suffix()}"
    if force_new:
        created = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "kms",
            "create-alias",
            env,
            [
                "--cli-input-json",
                json.dumps(
                    {"AliasName": alias_name, "TargetKeyId": key_id},
                    separators=(",", ":"),
                ),
            ],
        )
        if isinstance(created, dict):
            kms_record_runtime_payload(region, created)
        state["alias_name"] = alias_name
        return alias_name, key_id

    listed = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "list-aliases",
        env,
        ["--key-id", key_id, "--limit", "10"],
    )
    if isinstance(listed, dict):
        kms_record_runtime_payload(region, listed)
        aliases = listed.get("Aliases")
        if isinstance(aliases, list):
            for item in aliases:
                if not isinstance(item, dict):
                    continue
                alias = item.get("AliasName")
                if isinstance(alias, str) and alias.strip():
                    state["alias_name"] = alias.strip()
                    return alias.strip(), key_id

    alias_name = f"alias/stackyard-coverage-{kms_unique_suffix()}"
    run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "create-alias",
        env,
        [
            "--cli-input-json",
            json.dumps({"AliasName": alias_name, "TargetKeyId": key_id}, separators=(",", ":")),
        ],
    )
    state["alias_name"] = alias_name
    return alias_name, key_id


def kms_ensure_grant(aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], force_new: bool = False) -> tuple[str, str]:
    state = kms_runtime_state(region)
    key_id, _ = kms_ensure_encrypt_key(aws_bin, endpoint_url, region, env)
    grant_id = str(state.get("grant_id") or "").strip()
    if grant_id and not force_new:
        listed = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "kms",
            "list-grants",
            env,
            ["--key-id", key_id, "--limit", "10"],
        )
        if isinstance(listed, dict):
            kms_record_runtime_payload(region, listed)
            grant_id = str(state.get("grant_id") or grant_id).strip()
            if grant_id:
                return grant_id, key_id

    payload = {
        "KeyId": key_id,
        "Name": f"stackyard-grant-{kms_unique_suffix()}",
        "GranteePrincipal": str(state.get("grantee_principal") or KMS_DEFAULT_GRANTEE_PRINCIPAL),
        "RetiringPrincipal": str(state.get("retiring_principal") or KMS_DEFAULT_RETIRING_PRINCIPAL),
        "Operations": ["Encrypt", "Decrypt"],
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "create-grant",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(created, dict):
        kms_record_runtime_payload(region, created)
    grant_id = str(state.get("grant_id") or "").strip()
    return grant_id, key_id


def kms_ensure_ciphertext(
    aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], force_new: bool = False
) -> tuple[str, str]:
    state = kms_runtime_state(region)
    key_id, _ = kms_ensure_encrypt_key(aws_bin, endpoint_url, region, env)
    ciphertext = str(state.get("ciphertext_blob") or "").strip()
    if ciphertext and not force_new:
        return ciphertext, key_id

    payload = {"KeyId": key_id, "Plaintext": str(state.get("plaintext_b64") or KMS_DEFAULT_PLAINTEXT_B64)}
    encrypted = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "encrypt",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(encrypted, dict):
        kms_record_runtime_payload(region, encrypted)
    ciphertext = str(state.get("ciphertext_blob") or "").strip()
    return ciphertext, key_id


def kms_ensure_signature(
    aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], force_new: bool = False
) -> tuple[str, str, str, str]:
    state = kms_runtime_state(region)
    key_id, _ = kms_ensure_sign_key(aws_bin, endpoint_url, region, env)
    signature = str(state.get("signature") or "").strip()
    signing_algorithm = str(state.get("signing_algorithm") or "").strip()
    message = str(state.get("sign_message_b64") or KMS_DEFAULT_SIGN_MESSAGE_B64)
    if signature and not force_new:
        return signature, key_id, message, signing_algorithm

    payload = {
        "KeyId": key_id,
        "Message": message,
        "SigningAlgorithm": "RSASSA_PSS_SHA_256",
        "MessageType": "RAW",
    }
    signed = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "sign",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(signed, dict):
        kms_record_runtime_payload(region, signed)
    signature = str(state.get("signature") or "").strip()
    signing_algorithm = str(state.get("signing_algorithm") or "").strip()
    return signature, key_id, message, signing_algorithm


def kms_ensure_mac(aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], force_new: bool = False) -> tuple[str, str, str, str]:
    state = kms_runtime_state(region)
    key_id, _ = kms_ensure_mac_key(aws_bin, endpoint_url, region, env)
    mac = str(state.get("mac") or "").strip()
    mac_algorithm = str(state.get("mac_algorithm") or "").strip()
    message = str(state.get("mac_message_b64") or KMS_DEFAULT_MAC_MESSAGE_B64)
    if mac and not force_new:
        return mac, key_id, message, mac_algorithm

    payload = {
        "KeyId": key_id,
        "Message": message,
        "MacAlgorithm": "HMAC_SHA_256",
    }
    generated = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "generate-mac",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(generated, dict):
        kms_record_runtime_payload(region, generated)
    mac = str(state.get("mac") or "").strip()
    mac_algorithm = str(state.get("mac_algorithm") or "").strip()
    return mac, key_id, message, mac_algorithm


def kms_ensure_import_parameters(
    aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], key_id: str
) -> str:
    state = kms_runtime_state(region)
    payload = {
        "KeyId": key_id,
        "WrappingAlgorithm": str(state.get("wrapping_algorithm") or KMS_DEFAULT_WRAPPING_ALGORITHM),
        "WrappingKeySpec": str(state.get("wrapping_key_spec") or KMS_DEFAULT_WRAPPING_KEY_SPEC),
    }
    output = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "get-parameters-for-import",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(output, dict):
        kms_record_runtime_payload(region, output)
    return str(state.get("import_token") or "").strip()


def kms_ensure_imported_key_material(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    force_new_key: bool = False,
) -> str:
    key_id, _ = kms_ensure_encrypt_key(aws_bin, endpoint_url, region, env, force_new=force_new_key)
    token = kms_ensure_import_parameters(aws_bin, endpoint_url, region, env, key_id)
    if not token:
        return key_id
    payload = {
        "KeyId": key_id,
        "EncryptedKeyMaterial": KMS_DEFAULT_ENCRYPTED_KEY_MATERIAL_B64,
        "ImportToken": token,
        "ExpirationModel": "KEY_MATERIAL_DOES_NOT_EXPIRE",
    }
    run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "import-key-material",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    return key_id


def kms_ensure_custom_key_store(
    aws_bin: str, endpoint_url: str, region: str, env: dict[str, str], force_new: bool = False
) -> str:
    state = kms_runtime_state(region)
    custom_key_store_id = str(state.get("custom_key_store_id") or "").strip()
    if custom_key_store_id and not force_new:
        described = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "kms",
            "describe-custom-key-stores",
            env,
            ["--custom-key-store-id", custom_key_store_id, "--limit", "1"],
        )
        if isinstance(described, dict):
            stores = described.get("CustomKeyStores")
            if isinstance(stores, list) and stores:
                kms_record_runtime_payload(region, described)
                return custom_key_store_id

    name = f"stackyard-kms-store-{kms_unique_suffix()}"
    payload = {
        "CustomKeyStoreName": name,
        "CloudHsmClusterId": "cluster-1234567890abcdef0",
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "create-custom-key-store",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    if isinstance(created, dict):
        kms_record_runtime_payload(region, created)
    custom_key_store_id = str(state.get("custom_key_store_id") or "").strip()
    if not custom_key_store_id:
        described = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "kms",
            "describe-custom-key-stores",
            env,
            ["--limit", "10"],
        )
        if isinstance(described, dict):
            kms_record_runtime_payload(region, described)
        custom_key_store_id = str(state.get("custom_key_store_id") or "").strip()
    state["custom_key_store_name"] = name
    return custom_key_store_id


