def kms_ensure_tag(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    key_id: str,
) -> None:
    payload = {"KeyId": key_id, "Tags": [{"TagKey": "env", "TagValue": "coverage"}]}
    run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "kms",
        "tag-resource",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )


def keyspaces_unique_suffix() -> str:
    return str(int(time.time() * 1000) % 1000000).zfill(6)


def keyspaces_keyspace_arn(region: str, keyspace_name: str) -> str:
    return f"arn:aws:cassandra:{region}:123456789012:/keyspace/{keyspace_name}"


def keyspaces_table_arn(region: str, keyspace_name: str, table_name: str) -> str:
    return f"{keyspaces_keyspace_arn(region, keyspace_name)}/table/{table_name}"


def keyspaces_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("keyspaces", {})
    keyspace_name = str(state.get("keyspace_name") or KEYSPACES_DEFAULT_KEYSPACE_NAME).strip() or KEYSPACES_DEFAULT_KEYSPACE_NAME
    table_name = str(state.get("table_name") or KEYSPACES_DEFAULT_TABLE_NAME).strip() or KEYSPACES_DEFAULT_TABLE_NAME
    type_name = str(state.get("type_name") or KEYSPACES_DEFAULT_TYPE_NAME).strip() or KEYSPACES_DEFAULT_TYPE_NAME

    state["region"] = region
    state["keyspace_name"] = keyspace_name
    state["table_name"] = table_name
    state["restore_table_name"] = str(state.get("restore_table_name") or f"{table_name}_restored").strip() or f"{table_name}_restored"
    state["type_name"] = type_name
    state["keyspace_arn"] = keyspaces_keyspace_arn(region, keyspace_name)
    state["table_arn"] = keyspaces_table_arn(region, keyspace_name, table_name)
    state["resource_arn"] = str(state.get("resource_arn") or state["table_arn"])
    return state


def keyspaces_ensure_keyspace(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    force_new: bool = False,
) -> tuple[str, str]:
    state = keyspaces_runtime_state(region)
    keyspace_name = str(state.get("keyspace_name") or KEYSPACES_DEFAULT_KEYSPACE_NAME).strip() or KEYSPACES_DEFAULT_KEYSPACE_NAME
    if force_new:
        keyspace_name = f"{KEYSPACES_DEFAULT_KEYSPACE_NAME}_{keyspaces_unique_suffix()}"

    if not force_new:
        existing = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "keyspaces",
            "get-keyspace",
            env,
            ["--keyspace-name", keyspace_name],
        )
        if isinstance(existing, dict):
            keyspace_arn = str(existing.get("resourceArn") or keyspaces_keyspace_arn(region, keyspace_name)).strip()
            state["keyspace_name"] = keyspace_name
            state["keyspace_arn"] = keyspace_arn
            return keyspace_name, keyspace_arn

    payload = {
        "keyspaceName": keyspace_name,
        "tags": [{"key": "env", "value": "coverage"}],
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "keyspaces",
        "create-keyspace",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    keyspace_arn = keyspaces_keyspace_arn(region, keyspace_name)
    if isinstance(created, dict):
        keyspace_arn = str(created.get("resourceArn") or keyspace_arn).strip() or keyspace_arn
    else:
        existing = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "keyspaces",
            "get-keyspace",
            env,
            ["--keyspace-name", keyspace_name],
        )
        if isinstance(existing, dict):
            keyspace_arn = str(existing.get("resourceArn") or keyspace_arn).strip() or keyspace_arn

    state["keyspace_name"] = keyspace_name
    state["keyspace_arn"] = keyspace_arn
    return keyspace_name, keyspace_arn


def keyspaces_ensure_table(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    force_new: bool = False,
) -> tuple[str, str, str]:
    state = keyspaces_runtime_state(region)
    keyspace_name, keyspace_arn = keyspaces_ensure_keyspace(aws_bin, endpoint_url, region, env, force_new=False)
    table_name = str(state.get("table_name") or KEYSPACES_DEFAULT_TABLE_NAME).strip() or KEYSPACES_DEFAULT_TABLE_NAME
    if force_new:
        table_name = f"{KEYSPACES_DEFAULT_TABLE_NAME}_{keyspaces_unique_suffix()}"

    if not force_new:
        existing = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "keyspaces",
            "get-table",
            env,
            ["--keyspace-name", keyspace_name, "--table-name", table_name],
        )
        if isinstance(existing, dict):
            table_arn = str(existing.get("resourceArn") or keyspaces_table_arn(region, keyspace_name, table_name)).strip()
            state["keyspace_name"] = keyspace_name
            state["keyspace_arn"] = keyspace_arn
            state["table_name"] = table_name
            state["table_arn"] = table_arn
            state["resource_arn"] = table_arn
            return keyspace_name, table_name, table_arn

    payload = {
        "keyspaceName": keyspace_name,
        "tableName": table_name,
        "schemaDefinition": {
            "allColumns": [{"name": "pk", "type": "text"}],
            "partitionKeys": [{"name": "pk"}],
        },
        "tags": [{"key": "env", "value": "coverage"}],
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "keyspaces",
        "create-table",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )
    table_arn = keyspaces_table_arn(region, keyspace_name, table_name)
    if isinstance(created, dict):
        table_arn = str(created.get("resourceArn") or table_arn).strip() or table_arn
    else:
        existing = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "keyspaces",
            "get-table",
            env,
            ["--keyspace-name", keyspace_name, "--table-name", table_name],
        )
        if isinstance(existing, dict):
            table_arn = str(existing.get("resourceArn") or table_arn).strip() or table_arn

    state["keyspace_name"] = keyspace_name
    state["keyspace_arn"] = keyspace_arn
    state["table_name"] = table_name
    state["table_arn"] = table_arn
    state["resource_arn"] = table_arn
    return keyspace_name, table_name, table_arn


def keyspaces_ensure_type(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    force_new: bool = False,
) -> tuple[str, str]:
    state = keyspaces_runtime_state(region)
    keyspace_name, keyspace_arn = keyspaces_ensure_keyspace(aws_bin, endpoint_url, region, env, force_new=False)
    type_name = str(state.get("type_name") or KEYSPACES_DEFAULT_TYPE_NAME).strip() or KEYSPACES_DEFAULT_TYPE_NAME
    if force_new:
        type_name = f"{KEYSPACES_DEFAULT_TYPE_NAME}_{keyspaces_unique_suffix()}"

    if not force_new:
        existing = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "keyspaces",
            "get-type",
            env,
            ["--keyspace-name", keyspace_name, "--type-name", type_name],
        )
        if isinstance(existing, dict):
            state["keyspace_name"] = keyspace_name
            state["keyspace_arn"] = str(existing.get("keyspaceArn") or keyspace_arn)
            state["type_name"] = type_name
            return keyspace_name, type_name

    payload = {
        "keyspaceName": keyspace_name,
        "typeName": type_name,
        "fieldDefinitions": [{"name": "field1", "type": "text"}],
    }
    run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "keyspaces",
        "create-type",
        env,
        ["--cli-input-json", json.dumps(payload, separators=(",", ":"))],
    )

    state["keyspace_name"] = keyspace_name
    state["keyspace_arn"] = keyspace_arn
    state["type_name"] = type_name
    return keyspace_name, type_name


