def sns_topic_arn(region: str, topic_name: str) -> str:
    return f"arn:aws:sns:{region}:123456789012:{topic_name}"


def sns_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("sns", {})
    topic_name = str(state.get("topic_name") or SNS_DEFAULT_TOPIC_NAME)
    defaults = {
        "region": region,
        "topic_name": topic_name,
        "topic_arn": sns_topic_arn(region, topic_name),
        "platform_application_name": SNS_DEFAULT_PLATFORM_APPLICATION_NAME,
        "platform": SNS_DEFAULT_PLATFORM,
        "platform_application_arn": "",
        "endpoint_token": SNS_DEFAULT_ENDPOINT_TOKEN,
        "endpoint_arn": "",
        "subscription_arn": "",
        "pending_subscription_token": "",
        "queue_endpoint": SNS_DEFAULT_QUEUE_ENDPOINT,
        "email_endpoint": SNS_DEFAULT_EMAIL_ENDPOINT,
        "phone_number": SNS_DEFAULT_PHONE_NUMBER,
        "permission_label": SNS_DEFAULT_PERMISSION_LABEL,
        "data_protection_policy": SNS_DEFAULT_DATA_PROTECTION_POLICY,
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def sns_extract_token_from_subscription_arn(subscription_arn: str) -> str | None:
    arn = subscription_arn.strip()
    if not arn:
        return None
    suffix = arn.rsplit(":", 1)[-1].strip()
    if suffix.isdigit():
        return f"token-{suffix}"
    return None


def sns_ensure_topic(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = sns_runtime_state(region)
    topic_name = str(state.get("topic_name") or SNS_DEFAULT_TOPIC_NAME)
    data = run_aws_json(aws_bin, endpoint_url, region, "sns", "create-topic", env, ["--name", topic_name])
    if isinstance(data, dict):
        topic_arn = data.get("TopicArn")
        if isinstance(topic_arn, str) and topic_arn.strip():
            state["topic_arn"] = topic_arn
            return topic_arn
    return str(state.get("topic_arn") or sns_topic_arn(region, topic_name))


