def s3_ensure_multipart_upload(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    bucket_name: str,
    key: str,
    part_body: bytes | None = None,
) -> tuple[str, str]:
    state = s3_runtime_state(region)
    bucket = s3_ensure_bucket(aws_bin, endpoint_url, region, env, bucket_name)
    object_key = key.strip() or str(state["multipart_key"])
    upload_id = ""
    status_code, response_text = invoke_s3_create_multipart_upload_raw(
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        bucket=bucket,
        key=object_key,
    )
    if 200 <= status_code < 300:
        match = re.search(r"<UploadId>([^<]+)</UploadId>", response_text)
        if match:
            upload_id = match.group(1).strip()
    if not upload_id:
        created = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "s3api",
            "create-multipart-upload",
            env,
            ["--bucket", bucket, "--key", object_key],
        )
        if isinstance(created, dict):
            s3_record_runtime_payload(region, created)
            value = created.get("UploadId")
            if isinstance(value, str) and value.strip():
                upload_id = value.strip()
    if not upload_id:
        upload_id = str(state.get("multipart_upload_id") or "")

    etag = ""
    if upload_id:
        seed_body = part_body if part_body is not None else b"stackyard multipart part\n"
        status_code, _, response_headers = invoke_s3_upload_part_raw_detailed(
            endpoint_url=endpoint_url,
            region=region,
            env=env,
            bucket=bucket,
            key=object_key,
            upload_id=upload_id,
            part_number=1,
            body=seed_body,
        )
        if 200 <= status_code < 300:
            etag = str(response_headers.get("ETag") or response_headers.get("Etag") or "").strip().strip('"')
        if not etag:
            with tempfile.NamedTemporaryFile(prefix="stackyard-s3-part-", suffix=".bin", delete=False) as tmp:
                tmp.write(seed_body)
                part_path = tmp.name
            try:
                uploaded = run_aws_json(
                    aws_bin,
                    endpoint_url,
                    region,
                    "s3api",
                    "upload-part",
                    env,
                    [
                        "--bucket",
                        bucket,
                        "--key",
                        object_key,
                        "--upload-id",
                        upload_id,
                        "--part-number",
                        "1",
                        "--body",
                        part_path,
                    ],
                )
            finally:
                try:
                    os.unlink(part_path)
                except OSError:
                    pass
            if isinstance(uploaded, dict):
                s3_record_runtime_payload(region, uploaded)
                etag_value = uploaded.get("ETag")
                if isinstance(etag_value, str) and etag_value.strip():
                    etag = etag_value.strip().strip('"')
    if not etag:
        etag = str(state.get("multipart_part_etag") or "")
    state["multipart_key"] = object_key
    state["multipart_upload_id"] = upload_id
    state["multipart_part_etag"] = etag
    return upload_id, etag


def ecr_default_image_manifest(layer_digest: str | None = None) -> str:
    config_digest = hashlib.sha256(b"{}").hexdigest()
    manifest: dict[str, object] = {
        "schemaVersion": 2,
        "mediaType": "application/vnd.docker.distribution.manifest.v2+json",
        "config": {
            "mediaType": "application/vnd.docker.container.image.v1+json",
            "size": 2,
            "digest": f"sha256:{config_digest}",
        },
        "layers": [],
    }
    if layer_digest:
        manifest["layers"] = [
            {
                "mediaType": "application/vnd.docker.image.rootfs.diff.tar.gzip",
                "size": len(ECR_DEFAULT_LAYER_PART_BYTES),
                "digest": layer_digest,
            }
        ]
    return json.dumps(manifest, separators=(",", ":"))


def ecr_manifest_digest(image_manifest: str) -> str:
    return f"sha256:{hashlib.sha256(image_manifest.encode('utf-8')).hexdigest()}"


def ecr_repository_arn(region: str, registry_id: str, repository_name: str) -> str:
    return f"arn:aws:ecr:{region}:{registry_id}:repository/{repository_name}"


def ecr_default_lifecycle_policy_text() -> str:
    policy = {
        "rules": [
            {
                "rulePriority": 1,
                "description": "stackyard lifecycle",
                "selection": {
                    "tagStatus": "any",
                    "countType": "sinceImagePushed",
                    "countUnit": "days",
                    "countNumber": 30,
                },
                "action": {"type": "expire"},
            }
        ]
    }
    return json.dumps(policy, separators=(",", ":"))


def ecr_default_registry_policy_text() -> str:
    policy = {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Sid": "StackyardRegistryPolicy",
                "Effect": "Allow",
                "Principal": {"AWS": [f"arn:aws:iam::{ECR_DEFAULT_REGISTRY_ID}:root"]},
                "Action": ["ecr:ReplicateImage"],
                "Resource": "*",
            }
        ],
    }
    return json.dumps(policy, separators=(",", ":"))


def ecr_default_repository_policy_text(repository_arn: str) -> str:
    policy = {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Sid": "StackyardRepositoryPolicy",
                "Effect": "Allow",
                "Principal": {"AWS": [f"arn:aws:iam::{ECR_DEFAULT_REGISTRY_ID}:root"]},
                "Action": ["ecr:BatchGetImage", "ecr:GetDownloadUrlForLayer"],
                "Resource": repository_arn,
            }
        ],
    }
    return json.dumps(policy, separators=(",", ":"))


def ecr_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("ecr", {})
    registry_id = str(state.get("registry_id") or ECR_DEFAULT_REGISTRY_ID)
    repository_name = str(state.get("repository_name") or ECR_DEFAULT_REPOSITORY_NAME)
    repository_arn = str(state.get("repository_arn") or ecr_repository_arn(region, registry_id, repository_name))
    image_tag = str(state.get("image_tag") or ECR_DEFAULT_IMAGE_TAG)
    layer_part_blob = str(state.get("layer_part_blob") or base64.b64encode(ECR_DEFAULT_LAYER_PART_BYTES).decode("ascii"))
    layer_digest = str(state.get("layer_digest") or f"sha256:{hashlib.sha256(ECR_DEFAULT_LAYER_PART_BYTES).hexdigest()}")
    image_manifest = str(state.get("image_manifest") or ecr_default_image_manifest(layer_digest))
    image_digest = str(state.get("image_digest") or ecr_manifest_digest(image_manifest))
    pull_through_prefix = str(state.get("pull_through_prefix") or ECR_DEFAULT_PULL_THROUGH_PREFIX)
    template_prefix = str(state.get("template_prefix") or ECR_DEFAULT_TEMPLATE_PREFIX)
    lifecycle_policy_text = str(state.get("lifecycle_policy_text") or ecr_default_lifecycle_policy_text())
    registry_policy_text = str(state.get("registry_policy_text") or ecr_default_registry_policy_text())
    repository_policy_text = str(state.get("repository_policy_text") or ecr_default_repository_policy_text(repository_arn))
    upload_id = str(state.get("upload_id") or "")

    state.update(
        {
            "registry_id": registry_id,
            "repository_name": repository_name,
            "repository_arn": repository_arn,
            "image_tag": image_tag,
            "image_manifest": image_manifest,
            "image_digest": image_digest,
            "layer_part_blob": layer_part_blob,
            "layer_digest": layer_digest,
            "pull_through_prefix": pull_through_prefix,
            "template_prefix": template_prefix,
            "lifecycle_policy_text": lifecycle_policy_text,
            "registry_policy_text": registry_policy_text,
            "repository_policy_text": repository_policy_text,
            "upload_id": upload_id,
        }
    )
    return state


def ecr_record_runtime_payload(region: str, payload: dict) -> None:
    state = ecr_runtime_state(region)

    def _save_if_str(key: str, value) -> None:
        if isinstance(value, str) and value.strip():
            state[key] = value

    _save_if_str("registry_id", payload.get("registryId"))
    _save_if_str("repository_name", payload.get("repositoryName"))
    _save_if_str("repository_arn", payload.get("repositoryArn"))
    _save_if_str("image_digest", payload.get("imageDigest"))
    _save_if_str("upload_id", payload.get("uploadId"))
    _save_if_str("layer_digest", payload.get("layerDigest"))
    _save_if_str("pull_through_prefix", payload.get("ecrRepositoryPrefix"))
    _save_if_str("template_prefix", payload.get("repositoryPrefix"))

    repository = payload.get("repository")
    if isinstance(repository, dict):
        _save_if_str("repository_name", repository.get("repositoryName"))
        _save_if_str("repository_arn", repository.get("repositoryArn"))
        _save_if_str("registry_id", repository.get("registryId"))

    repositories = payload.get("repositories")
    if isinstance(repositories, list):
        for item in repositories:
            if isinstance(item, dict):
                _save_if_str("repository_name", item.get("repositoryName"))
                _save_if_str("repository_arn", item.get("repositoryArn"))
                _save_if_str("registry_id", item.get("registryId"))
                break

    image = payload.get("image")
    if isinstance(image, dict):
        image_id = image.get("imageId")
        if isinstance(image_id, dict):
            _save_if_str("image_tag", image_id.get("imageTag"))
            _save_if_str("image_digest", image_id.get("imageDigest"))

    image_id = payload.get("imageId")
    if isinstance(image_id, dict):
        _save_if_str("image_tag", image_id.get("imageTag"))
        _save_if_str("image_digest", image_id.get("imageDigest"))

    images = payload.get("images")
    if isinstance(images, list):
        for item in images:
            if not isinstance(item, dict):
                continue
            current_image_id = item.get("imageId")
            if isinstance(current_image_id, dict):
                _save_if_str("image_tag", current_image_id.get("imageTag"))
                _save_if_str("image_digest", current_image_id.get("imageDigest"))
                break

    pull_through_rules = payload.get("pullThroughCacheRules")
    if isinstance(pull_through_rules, list):
        for item in pull_through_rules:
            if isinstance(item, dict):
                _save_if_str("pull_through_prefix", item.get("ecrRepositoryPrefix"))
                break

    creation_templates = payload.get("repositoryCreationTemplates")
    if isinstance(creation_templates, list):
        for item in creation_templates:
            if isinstance(item, dict):
                _save_if_str("template_prefix", item.get("repositoryPrefix"))
                break

    registry_id = str(state.get("registry_id") or ECR_DEFAULT_REGISTRY_ID)
    repository_name = str(state.get("repository_name") or ECR_DEFAULT_REPOSITORY_NAME)
    if not str(state.get("repository_arn") or "").strip():
        state["repository_arn"] = ecr_repository_arn(region, registry_id, repository_name)
    if not str(state.get("repository_policy_text") or "").strip():
        state["repository_policy_text"] = ecr_default_repository_policy_text(str(state.get("repository_arn")))


def ecr_ensure_repository(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> tuple[str, str]:
    state = ecr_runtime_state(region)
    repository_name = str(state["repository_name"])

    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "describe-repositories",
        env,
        ["--repository-names", repository_name],
    )
    if isinstance(data, dict):
        ecr_record_runtime_payload(region, data)
    else:
        data = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "ecr",
            "create-repository",
            env,
            ["--repository-name", repository_name],
        )
        if isinstance(data, dict):
            ecr_record_runtime_payload(region, data)

    state = ecr_runtime_state(region)
    return str(state["repository_name"]), str(state["repository_arn"])


def ecr_ensure_pull_through_cache_rule(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = ecr_runtime_state(region)
    prefix = str(state["pull_through_prefix"])
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "describe-pull-through-cache-rules",
        env,
        ["--ecr-repository-prefixes", prefix],
    )
    if isinstance(data, dict):
        ecr_record_runtime_payload(region, data)
        rules = data.get("pullThroughCacheRules")
        if isinstance(rules, list) and rules:
            return str(ecr_runtime_state(region)["pull_through_prefix"])

    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "create-pull-through-cache-rule",
        env,
        ["--ecr-repository-prefix", prefix, "--upstream-registry-url", "public.ecr.aws"],
    )
    if isinstance(data, dict):
        ecr_record_runtime_payload(region, data)
    return str(ecr_runtime_state(region)["pull_through_prefix"])


def ecr_ensure_repository_creation_template(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = ecr_runtime_state(region)
    prefix = str(state["template_prefix"])
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "describe-repository-creation-templates",
        env,
        ["--prefixes", prefix],
    )
    if isinstance(data, dict):
        ecr_record_runtime_payload(region, data)
        templates = data.get("repositoryCreationTemplates")
        if isinstance(templates, list) and templates:
            return str(ecr_runtime_state(region)["template_prefix"])

    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "create-repository-creation-template",
        env,
        ["--prefix", prefix, "--description", "stackyard template", "--applied-for", "REPLICATION"],
    )
    if isinstance(data, dict):
        ecr_record_runtime_payload(region, data)
    return str(ecr_runtime_state(region)["template_prefix"])


def ecr_start_layer_upload(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    repository_name, _ = ecr_ensure_repository(aws_bin, endpoint_url, region, env)
    state = ecr_runtime_state(region)
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "initiate-layer-upload",
        env,
        ["--repository-name", repository_name, "--registry-id", str(state["registry_id"])],
    )
    if isinstance(data, dict):
        ecr_record_runtime_payload(region, data)
    return str(ecr_runtime_state(region).get("upload_id") or "")


def ecr_upload_layer_part(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    upload_id: str,
) -> bool:
    state = ecr_runtime_state(region)
    repository_name = str(state["repository_name"])
    blob = str(state["layer_part_blob"])
    part_last_byte = len(ECR_DEFAULT_LAYER_PART_BYTES) - 1
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "upload-layer-part",
        env,
        [
            "--repository-name",
            repository_name,
            "--registry-id",
            str(state["registry_id"]),
            "--upload-id",
            upload_id,
            "--part-first-byte",
            "0",
            "--part-last-byte",
            str(part_last_byte),
            "--layer-part-blob",
            blob,
        ],
    )
    return isinstance(data, dict)


def ecr_ensure_layer_uploaded(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = ecr_runtime_state(region)
    upload_id = ecr_start_layer_upload(aws_bin, endpoint_url, region, env)
    if not upload_id:
        return str(state["layer_digest"])
    if not ecr_upload_layer_part(aws_bin, endpoint_url, region, env, upload_id):
        return str(ecr_runtime_state(region)["layer_digest"])

    state = ecr_runtime_state(region)
    layer_digest = str(state["layer_digest"])
    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "ecr",
        "complete-layer-upload",
        env,
        [
            "--repository-name",
            str(state["repository_name"]),
            "--registry-id",
            str(state["registry_id"]),
            "--upload-id",
            upload_id,
            "--layer-digests",
            layer_digest,
        ],
    )
    if isinstance(data, dict):
        ecr_record_runtime_payload(region, data)
    return str(ecr_runtime_state(region)["layer_digest"])


