def eks_extract_update_id(payload: dict | None) -> str:
    if not isinstance(payload, dict):
        return ""
    update = payload.get("update")
    if isinstance(update, dict):
        value = update.get("id")
        if isinstance(value, str) and value.strip():
            return value.strip()
    ids = payload.get("updateIds")
    if isinstance(ids, list):
        for item in ids:
            if isinstance(item, str) and item.strip():
                return item.strip()
    return ""


def eks_extract_subscription_id(payload: dict | None) -> str:
    if not isinstance(payload, dict):
        return ""
    subscription = payload.get("subscription")
    if isinstance(subscription, dict):
        value = subscription.get("id")
        if isinstance(value, str) and value.strip():
            return value.strip()
    subscriptions = payload.get("subscriptions")
    if isinstance(subscriptions, list):
        for item in subscriptions:
            if not isinstance(item, dict):
                continue
            value = item.get("id")
            if isinstance(value, str) and value.strip():
                return value.strip()
    return ""


def eks_extract_association_id(payload: dict | None) -> str:
    if not isinstance(payload, dict):
        return ""
    association = payload.get("association")
    if isinstance(association, dict):
        value = association.get("associationId")
        if isinstance(value, str) and value.strip():
            return value.strip()
    associations = payload.get("associations")
    if isinstance(associations, list):
        for item in associations:
            if not isinstance(item, dict):
                continue
            value = item.get("associationId")
            if isinstance(value, str) and value.strip():
                return value.strip()
    return ""


def eks_extract_capability_name(payload: dict | None) -> str:
    if not isinstance(payload, dict):
        return ""
    capability = payload.get("capability")
    if isinstance(capability, dict):
        name = capability.get("capabilityName")
        if isinstance(name, str) and name.strip():
            return name.strip()
    capabilities = payload.get("capabilities")
    if isinstance(capabilities, list):
        for item in capabilities:
            if not isinstance(item, dict):
                continue
            name = item.get("capabilityName")
            if isinstance(name, str) and name.strip():
                return name.strip()
    return ""


def eks_invoke_raw_operation(
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    operation: str,
    payload: dict[str, object],
) -> tuple[int, str, dict[str, object] | None]:
    endpoint = Endpoint(
        service="eks",
        cli_service="eks",
        operation=operation,
        cli_operation=pascal_to_kebab(operation),
        source="raw-seed",
    )
    status_code, response_text = invoke_raw_endpoint(endpoint, endpoint_url, region, env, payload)
    response_payload: dict[str, object] | None = None
    if 200 <= status_code < 300:
        try:
            parsed = json.loads(response_text) if response_text.strip() else {}
        except json.JSONDecodeError:
            parsed = None
        if isinstance(parsed, dict):
            response_payload = parsed
    return status_code, response_text, response_payload


def eks_ensure_cluster(aws_bin: str, endpoint_url: str, region: str, env: dict[str, str]) -> str:
    state = eks_runtime_state(region)
    cluster_name = str(state.get("cluster_name", EKS_DEFAULT_CLUSTER_NAME)).strip() or EKS_DEFAULT_CLUSTER_NAME
    role_arn = str(state.get("role_arn", EKS_DEFAULT_ROLE_ARN)).strip() or EKS_DEFAULT_ROLE_ARN
    subnet_id = str(state.get("subnet_id", EKS_DEFAULT_SUBNET_ID)).strip() or EKS_DEFAULT_SUBNET_ID

    describe = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "eks",
        "describe-cluster",
        env,
        ["--name", cluster_name],
    )
    if not describe:
        create_payload = {
            "name": cluster_name,
            "roleArn": role_arn,
            "resourcesVpcConfig": {"subnetIds": [subnet_id], "endpointPublicAccess": True},
        }
        run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "eks",
            "create-cluster",
            env,
            ["--cli-input-json", json.dumps(create_payload, separators=(",", ":"))],
        )
        describe = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "eks",
            "describe-cluster",
            env,
            ["--name", cluster_name],
        )

    if isinstance(describe, dict):
        cluster = describe.get("cluster")
        if isinstance(cluster, dict):
            name = cluster.get("name")
            if isinstance(name, str) and name.strip():
                cluster_name = name.strip()
                state["cluster_name"] = cluster_name
            arn = cluster.get("arn")
            if isinstance(arn, str) and arn.strip():
                state["cluster_arn"] = arn.strip()
    if not str(state.get("cluster_arn", "")).strip():
        state["cluster_arn"] = eks_cluster_arn(region, cluster_name)
    return cluster_name


