    if isinstance(described, dict):
        redshift_record_runtime_payload(region, described)
        return data_share_arn, consumer_identifier

    authorized = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "redshift",
        "authorize-data-share",
        env,
        [
            "--cli-input-json",
            json.dumps(
                {
                    "DataShareArn": data_share_arn,
                    "ConsumerIdentifier": consumer_identifier,
                    "AllowWrites": False,
                },
                separators=(",", ":"),
            ),
        ],
    )
    if isinstance(authorized, dict):
        redshift_record_runtime_payload(region, authorized)
    return data_share_arn, consumer_identifier


