def redshift_ensure_usage_limit(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = redshift_runtime_state(region)
    cluster_identifier = redshift_ensure_cluster(aws_bin, endpoint_url, region, env)
    limit_id = str(state["usage_limit_id"])

    described = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "redshift",
        "describe-usage-limits",
        env,
        ["--cluster-identifier", cluster_identifier],
    )
    if isinstance(described, dict):
        redshift_record_runtime_payload(region, described)
        limits = described.get("UsageLimits")
        if isinstance(limits, list):
            for item in limits:
                if not isinstance(item, dict):
                    continue
                candidate_id = str(item.get("UsageLimitId", "")).strip()
                if not candidate_id:
                    continue
                state["usage_limit_id"] = candidate_id
                return candidate_id

    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "redshift",
        "create-usage-limit",
        env,
        [
            "--cluster-identifier",
            cluster_identifier,
            "--feature-type",
            "spectrum",
            "--limit-type",
            "data-scanned",
            "--amount",
            "1",
            "--period",
            "daily",
            "--breach-action",
            "log",
        ],
    )
    if isinstance(created, dict):
        redshift_record_runtime_payload(region, created)
    return str(redshift_runtime_state(region).get("usage_limit_id", limit_id))


