def redshift_ensure_partner(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> tuple[str, str, str, str]:
    state = redshift_runtime_state(region)
    cluster_identifier = redshift_ensure_cluster(aws_bin, endpoint_url, region, env)
    account_id = str(state["partner_account_id"])
    database_name = str(state["partner_database_name"])
    partner_name = str(state["partner_name"])

    described = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "redshift",
        "describe-partners",
        env,
        [
            "--account-id",
            account_id,
            "--cluster-identifier",
            cluster_identifier,
            "--database-name",
            database_name,
            "--partner-name",
            partner_name,
        ],
    )
    if isinstance(described, dict):
        redshift_record_runtime_payload(region, described)
        partners = described.get("PartnerIntegrations")
        if isinstance(partners, list):
            for item in partners:
                if not isinstance(item, dict):
                    continue
                if str(item.get("AccountId", "")).strip() != account_id:
                    continue
                if str(item.get("ClusterIdentifier", "")).strip() != cluster_identifier:
                    continue
                if str(item.get("DatabaseName", "")).strip() != database_name:
                    continue
                if str(item.get("PartnerName", "")).strip() != partner_name:
                    continue
                return account_id, cluster_identifier, database_name, partner_name

    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "redshift",
        "add-partner",
        env,
        [
            "--account-id",
            account_id,
            "--cluster-identifier",
            cluster_identifier,
            "--database-name",
            database_name,
            "--partner-name",
            partner_name,
        ],
    )
    if isinstance(created, dict):
        redshift_record_runtime_payload(region, created)
    return account_id, cluster_identifier, database_name, partner_name


