def lambda_function_arn(region: str, function_name: str) -> str:
    return f"arn:aws:lambda:{region}:123456789012:function:{function_name}"


def lambda_alias_arn(region: str, function_name: str, alias_name: str) -> str:
    return f"arn:aws:lambda:{region}:123456789012:function:{function_name}:{alias_name}"


def lambda_layer_arn(region: str, layer_name: str) -> str:
    return f"arn:aws:lambda:{region}:123456789012:layer:{layer_name}"


def lambda_layer_version_arn(region: str, layer_name: str, version: str) -> str:
    return f"arn:aws:lambda:{region}:123456789012:layer:{layer_name}:{version}"


def lambda_codesigning_arn(region: str, config_id: str) -> str:
    return f"arn:aws:lambda:{region}:123456789012:code-signing-config:{config_id}"


def lambda_runtime_state(region: str) -> dict[str, object]:
    state = RUNTIME_STATE.setdefault("lambda", {})
    function_name = str(state.get("function_name", LAMBDA_DEFAULT_FUNCTION_NAME)).strip() or LAMBDA_DEFAULT_FUNCTION_NAME
    alias_name = str(state.get("alias_name", LAMBDA_DEFAULT_ALIAS_NAME)).strip() or LAMBDA_DEFAULT_ALIAS_NAME
    layer_name = str(state.get("layer_name", LAMBDA_DEFAULT_LAYER_NAME)).strip() or LAMBDA_DEFAULT_LAYER_NAME
    version = str(state.get("function_version", "1")).strip() or "1"
    layer_version = str(state.get("layer_version", "1")).strip() or "1"
    defaults = {
        "function_name": function_name,
        "function_arn": lambda_function_arn(region, function_name),
        "role_arn": LAMBDA_DEFAULT_ROLE_ARN,
        "runtime": LAMBDA_DEFAULT_RUNTIME,
        "handler": LAMBDA_DEFAULT_HANDLER,
        "function_version": version,
        "alias_name": alias_name,
        "alias_arn": lambda_alias_arn(region, function_name, alias_name),
        "event_source_mapping_uuid": "esm-00000001",
        "event_source_arn": LAMBDA_DEFAULT_EVENT_SOURCE_ARN,
        "layer_name": layer_name,
        "layer_version": layer_version,
        "layer_arn": lambda_layer_arn(region, layer_name),
        "layer_version_arn": lambda_layer_version_arn(region, layer_name, layer_version),
        "code_signing_config_id": "csc-00000001",
        "code_signing_config_arn": lambda_codesigning_arn(region, "csc-00000001"),
        "function_statement_id": LAMBDA_DEFAULT_FUNCTION_STATEMENT_ID,
        "layer_statement_id": LAMBDA_DEFAULT_LAYER_STATEMENT_ID,
        "capacity_provider_name": LAMBDA_DEFAULT_CAPACITY_PROVIDER_NAME,
        "capacity_provider_arn": f"arn:aws:lambda:{region}:123456789012:capacity-provider:{LAMBDA_DEFAULT_CAPACITY_PROVIDER_NAME}",
        "durable_execution_arn": LAMBDA_DEFAULT_DURABLE_EXECUTION_ARN,
        "checkpoint_token": "stackyard-checkpoint-000001",
        "callback_id": LAMBDA_DEFAULT_CALLBACK_ID,
        "zip_b64": LAMBDA_DEFAULT_ZIP_BASE64,
    }
    for key, value in defaults.items():
        state.setdefault(key, value)
    return state


def lambda_record_runtime_payload(region: str, payload: object) -> None:
    state = lambda_runtime_state(region)

    def _set_str(key: str, value: object) -> None:
        if isinstance(value, str) and value.strip():
            state[key] = value.strip()

    def _walk(node: object) -> None:
        if isinstance(node, dict):
            function_name = node.get("FunctionName")
            if isinstance(function_name, str) and function_name.strip():
                state["function_name"] = function_name.strip()
                state["function_arn"] = lambda_function_arn(region, function_name.strip())
            function_arn = node.get("FunctionArn")
            if isinstance(function_arn, str) and function_arn.strip():
                value = function_arn.strip()
                state["function_arn"] = value
                marker = ":function:"
                if marker in value:
                    tail = value.split(marker, 1)[1]
                    if ":" in tail:
                        fn_name, qualifier = tail.split(":", 1)
                        if fn_name:
                            state["function_name"] = fn_name
                        if qualifier and qualifier not in {"$LATEST"}:
                            state["alias_name"] = qualifier
                    elif tail:
                        state["function_name"] = tail

            alias_arn = node.get("AliasArn")
            if isinstance(alias_arn, str) and alias_arn.strip():
                state["alias_arn"] = alias_arn.strip()
            alias_name = node.get("Name")
            if isinstance(alias_name, str) and alias_name.strip():
                state["alias_name"] = alias_name.strip()
            function_version = node.get("FunctionVersion")
            if isinstance(function_version, str) and function_version.strip():
                state["function_version"] = function_version.strip()

            _set_str("event_source_mapping_uuid", node.get("UUID"))
            _set_str("capacity_provider_name", node.get("CapacityProviderName"))
            _set_str("capacity_provider_arn", node.get("CapacityProviderArn"))
            _set_str("durable_execution_arn", node.get("DurableExecutionArn"))
            _set_str("checkpoint_token", node.get("CheckpointToken"))
            _set_str("code_signing_config_arn", node.get("CodeSigningConfigArn"))
            _set_str("code_signing_config_id", node.get("CodeSigningConfigId"))

            csc_obj = node.get("CodeSigningConfig")
            if isinstance(csc_obj, dict):
                _set_str("code_signing_config_arn", csc_obj.get("CodeSigningConfigArn"))
                _set_str("code_signing_config_id", csc_obj.get("CodeSigningConfigId"))

            layer_name = node.get("LayerName")
            if isinstance(layer_name, str) and layer_name.strip():
                state["layer_name"] = layer_name.strip()
                state["layer_arn"] = lambda_layer_arn(region, layer_name.strip())
            layer_arn = node.get("LayerArn")
            if isinstance(layer_arn, str) and layer_arn.strip():
                value = layer_arn.strip()
                state["layer_arn"] = value
                marker = ":layer:"
                if marker in value:
                    name = value.split(marker, 1)[1]
                    if name:
                        state["layer_name"] = name
            version = node.get("Version")
            if isinstance(version, int):
                state["layer_version"] = str(version)
            elif isinstance(version, str) and version.strip().isdigit():
                state["layer_version"] = version.strip()
            layer_version_arn = node.get("LayerVersionArn")
            if isinstance(layer_version_arn, str) and layer_version_arn.strip():
                state["layer_version_arn"] = layer_version_arn.strip()
                value = layer_version_arn.strip()
                marker = ":layer:"
                if marker in value:
                    tail = value.split(marker, 1)[1]
                    parts = tail.rsplit(":", 1)
                    if len(parts) == 2:
                        layer_name_part = parts[0].strip()
                        layer_version_part = parts[1].strip()
                        if layer_name_part:
                            state["layer_name"] = layer_name_part
                            state["layer_arn"] = lambda_layer_arn(region, layer_name_part)
                        if layer_version_part:
                            state["layer_version"] = layer_version_part

            statement = node.get("Statement")
            if isinstance(statement, str) and statement.strip():
                try:
                    parsed = json.loads(statement)
                except Exception:  # noqa: BLE001
                    parsed = None
                if isinstance(parsed, dict):
                    sid = parsed.get("Sid")
                    if isinstance(sid, str) and sid.strip():
                        state["function_statement_id"] = sid.strip()

            for value in node.values():
                _walk(value)
        elif isinstance(node, list):
            for item in node:
                _walk(item)

    _walk(payload)


def lambda_unique_suffix() -> str:
    return str(int(time.time() * 1000) % 1000000)


def lambda_ensure_function(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> tuple[str, str]:
    state = lambda_runtime_state(region)
    function_name = str(state.get("function_name", LAMBDA_DEFAULT_FUNCTION_NAME))

    data = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "lambda",
        "get-function",
        env,
        ["--function-name", function_name],
    )
    if isinstance(data, dict):
        lambda_record_runtime_payload(region, data)
        return str(state["function_name"]), str(state["function_arn"])

    create_payload = {
        "FunctionName": function_name,
        "Runtime": str(state.get("runtime", LAMBDA_DEFAULT_RUNTIME)),
        "Role": str(state.get("role_arn", LAMBDA_DEFAULT_ROLE_ARN)),
        "Handler": str(state.get("handler", LAMBDA_DEFAULT_HANDLER)),
        "Code": {"ZipFile": str(state.get("zip_b64", LAMBDA_DEFAULT_ZIP_BASE64))},
        "Publish": True,
        "Architectures": ["x86_64"],
    }
    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "lambda",
        "create-function",
        env,
        ["--cli-input-json", json.dumps(create_payload, separators=(",", ":"))],
    )
    if isinstance(created, dict):
        lambda_record_runtime_payload(region, created)

    versions = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "lambda",
        "list-versions-by-function",
        env,
        ["--function-name", function_name],
    )
    published_version = ""
    if isinstance(versions, dict):
        lambda_record_runtime_payload(region, versions)
        items = versions.get("Versions")
        if isinstance(items, list):
            for item in items:
                if not isinstance(item, dict):
                    continue
                version = item.get("Version")
                if isinstance(version, str) and version.strip().isdigit():
                    published_version = version.strip()
                    break
    if not published_version:
        published = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "lambda",
            "publish-version",
            env,
            ["--function-name", function_name],
        )
        if isinstance(published, dict):
            lambda_record_runtime_payload(region, published)
            version = published.get("Version")
            if isinstance(version, str) and version.strip():
                published_version = version.strip()
    if published_version:
        state["function_version"] = published_version
    return str(state["function_name"]), str(state["function_arn"])


def lambda_ensure_alias(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> tuple[str, str]:
    state = lambda_runtime_state(region)
    function_name, _ = lambda_ensure_function(aws_bin, endpoint_url, region, env)
    alias_name = str(state.get("alias_name", LAMBDA_DEFAULT_ALIAS_NAME))
    function_version = str(state.get("function_version", "1"))

    alias = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "lambda",
        "get-alias",
        env,
        ["--function-name", function_name, "--name", alias_name],
    )
    if isinstance(alias, dict):
        lambda_record_runtime_payload(region, alias)
        return alias_name, str(state.get("alias_arn", lambda_alias_arn(region, function_name, alias_name)))

    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "lambda",
        "create-alias",
        env,
        [
            "--function-name",
            function_name,
            "--name",
            alias_name,
            "--function-version",
            function_version,
        ],
    )
    if isinstance(created, dict):
        lambda_record_runtime_payload(region, created)
    return alias_name, str(state.get("alias_arn", lambda_alias_arn(region, function_name, alias_name)))


def lambda_ensure_code_signing_config(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = lambda_runtime_state(region)
    arn = str(state.get("code_signing_config_arn", "")).strip()
    if arn:
        current = run_aws_json(
            aws_bin,
            endpoint_url,
            region,
            "lambda",
            "get-code-signing-config",
            env,
            ["--code-signing-config-arn", arn],
        )
        if isinstance(current, dict):
            lambda_record_runtime_payload(region, current)
            return str(state.get("code_signing_config_arn", arn))

    created = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "lambda",
        "create-code-signing-config",
        env,
        [
            "--cli-input-json",
            json.dumps(
                {
                    "Description": "stackyard coverage",
                    "AllowedPublishers": {"SigningProfileVersionArns": [LAMBDA_DEFAULT_CODE_SIGNING_PROFILE_ARN]},
                    "CodeSigningPolicies": {"UntrustedArtifactOnDeployment": "Warn"},
                },
                separators=(",", ":"),
            ),
        ],
    )
    if isinstance(created, dict):
        lambda_record_runtime_payload(region, created)
        return str(state.get("code_signing_config_arn", arn))

    listed = run_aws_json(
        aws_bin,
        endpoint_url,
        region,
        "lambda",
        "list-code-signing-configs",
        env,
        ["--max-items", "10"],
    )
    if isinstance(listed, dict):
        lambda_record_runtime_payload(region, listed)
        items = listed.get("CodeSigningConfigs")
        if isinstance(items, list) and items:
            first = items[0]
            if isinstance(first, dict):
                csc = first.get("CodeSigningConfig")
                if isinstance(csc, dict):
                    lambda_record_runtime_payload(region, csc)
    return str(state.get("code_signing_config_arn", arn))


def lambda_ensure_event_source_mapping(
    aws_bin: str,
    endpoint_url: str,
    region: str,
    env: dict[str, str],
) -> str:
    state = lambda_runtime_state(region)
