        op = endpoint.operation
        unique = str(int(time.time() * 1000) % 1000000)
        state = RUNTIME_STATE.setdefault("dsql", {})

        def _replace_payload(values: dict[str, object]) -> None:
            hydrated.clear()
            hydrated.update(values)

        def _cluster_identifier(seed: str) -> str:
            cleaned = "".join(ch for ch in seed.lower() if ch.isalnum())
            if not cleaned:
                cleaned = "dsql"
            cleaned = (cleaned + "0123456789" * 4)[:26]
            return cleaned

        def _cluster_arn(cluster_identifier: str) -> str:
            return f"arn:aws:dsql:{region}:123456789012:cluster/{cluster_identifier}"

        def _ensure_cluster() -> tuple[str, str]:
            identifier = str(state.get("cluster_identifier", "")).strip()
            if identifier:
                existing = run_aws_json(
                    aws_bin,
                    endpoint_url,
                    region,
                    "dsql",
                    "get-cluster",
                    env,
                    ["--identifier", identifier],
                )
                if isinstance(existing, dict):
                    return identifier, _cluster_arn(identifier)
            create_payload = {
                "deletionProtectionEnabled": False,
                "clientToken": f"coverage-{unique}",
            }
            created = run_aws_json(
                aws_bin,
                endpoint_url,
                region,
                "dsql",
                "create-cluster",
                env,
                ["--cli-input-json", json.dumps(create_payload, separators=(",", ":"))],
            )
            created_identifier = ""
            created_arn = ""
            if isinstance(created, dict):
                observed_identifier = created.get("identifier")
                if isinstance(observed_identifier, str):
                    created_identifier = observed_identifier.strip()
                observed_arn = created.get("arn")
                if isinstance(observed_arn, str):
                    created_arn = observed_arn.strip()
            if not created_identifier:
                listed = run_aws_json(
                    aws_bin,
                    endpoint_url,
                    region,
                    "dsql",
                    "list-clusters",
                    env,
                    ["--max-results", "100"],
                )
                if isinstance(listed, dict):
                    clusters = listed.get("clusters")
                    if isinstance(clusters, list):
                        for cluster in clusters:
                            if not isinstance(cluster, dict):
                                continue
                            observed_identifier = cluster.get("identifier")
                            if isinstance(observed_identifier, str) and observed_identifier.strip():
                                created_identifier = observed_identifier.strip()
                                break
            if not created_identifier:
                created_identifier = _cluster_identifier(f"coverage{unique}")
            if not created_arn:
                created_arn = _cluster_arn(created_identifier)
            state["cluster_identifier"] = created_identifier
            state["cluster_arn"] = created_arn
            return created_identifier, created_arn

        def _put_policy_raw(identifier: str) -> str:
            put_payload = {
                "policy": '{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Principal":{"AWS":"*"},"Action":"dsql:GetCluster","Resource":"*"}]}',
                "clientToken": f"coverage-policy-{unique}",
            }
            endpoint_def = Endpoint(
                service="dsql",
                cli_service="dsql",
                operation="PutClusterPolicy",
                cli_operation="put-cluster-policy",
                source="hydration",
            )
            status_code, response_text = invoke_raw_endpoint(endpoint_def, endpoint_url, region, env, {"identifier": identifier, **put_payload})
            if not (200 <= status_code < 300):
                return ""
            try:
                data = json.loads(response_text) if response_text.strip() else {}
            except json.JSONDecodeError:
                return ""
            if not isinstance(data, dict):
                return ""
            observed = data.get("policyVersion")
            if isinstance(observed, str):
                return observed.strip()
            return ""

        def _ensure_policy() -> tuple[str, str]:
            identifier, _ = _ensure_cluster()
            put_payload = {
                "policy": '{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Principal":{"AWS":"*"},"Action":"dsql:GetCluster","Resource":"*"}]}',
                "clientToken": f"coverage-policy-{unique}",
            }
            out = run_aws_json(
                aws_bin,
                endpoint_url,
                region,
                "dsql",
                "put-cluster-policy",
                env,
                ["--identifier", identifier, "--cli-input-json", json.dumps(put_payload, separators=(",", ":"))],
            )
            policy_version = ""
            if isinstance(out, dict):
                observed = out.get("policyVersion")
                if isinstance(observed, str):
                    policy_version = observed.strip()
            if not policy_version:
                policy_version = _put_policy_raw(identifier)
            if not policy_version:
                policy_version = str(state.get("policy_version", "")).strip() or "v1"
            state["policy_version"] = policy_version
            return identifier, policy_version

        def _ensure_tag() -> tuple[str, str]:
            identifier, arn = _ensure_cluster()
            run_aws_json(
                aws_bin,
                endpoint_url,
                region,
                "dsql",
                "tag-resource",
                env,
                ["--resource-arn", arn, "--tags", "env=coverage,team=stackyard"],
            )
            state["cluster_identifier"] = identifier
            state["cluster_arn"] = arn
            return identifier, arn

        if op == "CreateCluster":
            _replace_payload(
                {
                    "deletionProtectionEnabled": False,
                    "clientToken": f"create-{unique}",
                }
            )
            return hydrated

        if op == "DeleteCluster":
            identifier, _ = _ensure_cluster()
            _replace_payload({"identifier": identifier, "clientToken": f"delete-{unique}"})
            return hydrated

        if op == "GetCluster":
            identifier, _ = _ensure_cluster()
            _replace_payload({"identifier": identifier})
            return hydrated

