    if endpoint.service == "lightsail":
        hydrated = copy.deepcopy(payload)
        if not isinstance(hydrated, dict):
            return payload

        op = endpoint.operation
        reseed_prefixes = ("Delete", "Detach", "Stop", "Release", "Close", "Open", "Copy", "Export", "Setup")
        force_reseed = op.startswith(reseed_prefixes) or op in {"SetIpAddressType"}
        lightsail_seed_runtime_state(aws_bin, endpoint_url, region, env, force=force_reseed)
        state = lightsail_runtime_state(region)

        instance_name = str(state.get("instance_name", LIGHTSAIL_DEFAULT_INSTANCE_NAME))
        instance_snapshot_name = str(state.get("instance_snapshot_name", LIGHTSAIL_DEFAULT_INSTANCE_SNAPSHOT_NAME))
        disk_name = str(state.get("disk_name", LIGHTSAIL_DEFAULT_DISK_NAME))
        disk_snapshot_name = str(state.get("disk_snapshot_name", LIGHTSAIL_DEFAULT_DISK_SNAPSHOT_NAME))
        load_balancer_name = str(state.get("load_balancer_name", LIGHTSAIL_DEFAULT_LOAD_BALANCER_NAME))
        certificate_name = str(state.get("certificate_name", LIGHTSAIL_DEFAULT_CERTIFICATE_NAME))
        distribution_name = str(state.get("distribution_name", LIGHTSAIL_DEFAULT_DISTRIBUTION_NAME))
        domain_name = str(state.get("domain_name", LIGHTSAIL_DEFAULT_DOMAIN_NAME))
        domain_entry_id = str(state.get("domain_entry_id", "de-1"))
        bucket_name = str(state.get("bucket_name", LIGHTSAIL_DEFAULT_BUCKET_NAME))
        bucket_access_key_id = str(state.get("bucket_access_key_id", "AKIASTACKYARDLS"))
        container_service_name = str(state.get("container_service_name", LIGHTSAIL_DEFAULT_CONTAINER_SERVICE_NAME))
        relational_database_name = str(state.get("relational_database_name", LIGHTSAIL_DEFAULT_RELATIONAL_DATABASE_NAME))
        relational_database_snapshot_name = str(
            state.get("relational_database_snapshot_name", LIGHTSAIL_DEFAULT_RELATIONAL_DATABASE_SNAPSHOT_NAME)
        )
        relational_database_log_stream_name = str(state.get("relational_database_log_stream_name", "error"))
        static_ip_name = str(state.get("static_ip_name", LIGHTSAIL_DEFAULT_STATIC_IP_NAME))
        key_pair_name = str(state.get("key_pair_name", LIGHTSAIL_DEFAULT_KEY_PAIR_NAME))
        alarm_name = str(state.get("alarm_name", LIGHTSAIL_DEFAULT_ALARM_NAME))
        operation_id = str(state.get("operation_id", ""))
        auto_snapshot_date = str(state.get("auto_snapshot_date", datetime.datetime.now(datetime.UTC).strftime("%Y-%m-%d")))
        availability_zone = str(state.get("availability_zone", LIGHTSAIL_DEFAULT_AVAILABILITY_ZONE))
        blueprint_id = str(state.get("blueprint_id", LIGHTSAIL_DEFAULT_BLUEPRINT_ID))
        bundle_id = str(state.get("bundle_id", LIGHTSAIL_DEFAULT_BUNDLE_ID))
        bucket_bundle_id = str(state.get("bucket_bundle_id", LIGHTSAIL_DEFAULT_BUCKET_BUNDLE_ID))
        distribution_bundle_id = str(state.get("distribution_bundle_id", LIGHTSAIL_DEFAULT_DISTRIBUTION_BUNDLE_ID))
        relational_database_blueprint_id = str(
            state.get("relational_database_blueprint_id", LIGHTSAIL_DEFAULT_RELATIONAL_DATABASE_BLUEPRINT_ID)
        )
        relational_database_bundle_id = str(
            state.get("relational_database_bundle_id", LIGHTSAIL_DEFAULT_RELATIONAL_DATABASE_BUNDLE_ID)
        )

        now = datetime.datetime.now(datetime.UTC)
        start_time = (now - datetime.timedelta(hours=1)).strftime("%Y-%m-%dT%H:%M:%SZ")
        end_time = now.strftime("%Y-%m-%dT%H:%M:%SZ")
        unique = str(int(time.time() * 1000) % 1000000)

        if op in {"UpdateBucket", "UpdateBucketBundle", "GetBucketAccessKeys", "GetBucketMetricData"}:
            def _get_first_bucket_name() -> str:
                bucket_data_local = run_aws_json(aws_bin, endpoint_url, region, "lightsail", "get-buckets", env)
                if isinstance(bucket_data_local, dict):
                    buckets_local = bucket_data_local.get("buckets")
                    if isinstance(buckets_local, list):
                        for item_local in buckets_local:
                            if not isinstance(item_local, dict):
                                continue
                            name_local = item_local.get("name")
                            if isinstance(name_local, str) and name_local.strip():
                                return name_local.strip()
                return ""

            active_bucket_name = _get_first_bucket_name()
            if not active_bucket_name:
                candidate_bucket_name = f"{LIGHTSAIL_DEFAULT_BUCKET_NAME}-{unique}"
                run_aws_json(
                    aws_bin,
                    endpoint_url,
                    region,
                    "lightsail",
                    "create-bucket",
                    env,
                    [
                        "--cli-input-json",
                        json.dumps(
                            {
                                "bucketName": candidate_bucket_name,
                                "bundleId": bucket_bundle_id,
                                "enableObjectVersioning": False,
                            },
                            separators=(",", ":"),
                        ),
                    ],
                )
                active_bucket_name = _get_first_bucket_name() or candidate_bucket_name
            state["bucket_name"] = active_bucket_name
            bucket_name = active_bucket_name
            if op == "GetBucketAccessKeys":
                run_aws_json(
                    aws_bin,
                    endpoint_url,
                    region,
                    "lightsail",
                    "create-bucket-access-key",
                    env,
                    ["--bucket-name", bucket_name],
                )
                keys_data = run_aws_json(
                    aws_bin,
                    endpoint_url,
                    region,
                    "lightsail",
                    "get-bucket-access-keys",
                    env,
                    ["--bucket-name", bucket_name],
                )
                if isinstance(keys_data, dict):
                    lightsail_record_runtime_payload(region, keys_data)
                    bucket_access_key_id = str(
                        lightsail_runtime_state(region).get("bucket_access_key_id", bucket_access_key_id)
                    )

        if op == "UpdateDomainEntry":
            domains_data = run_aws_json(aws_bin, endpoint_url, region, "lightsail", "get-domains", env)
            found_domain = ""
            found_entry_id = ""
            if isinstance(domains_data, dict):
                domains = domains_data.get("domains")
                if isinstance(domains, list):
                    for domain_item in domains:
                        if not isinstance(domain_item, dict):
                            continue
                        name = domain_item.get("name")
                        if isinstance(name, str) and name.strip():
                            if not found_domain:
                                found_domain = name.strip()
                            if name.strip() == domain_name:
                                found_domain = name.strip()
                            entries = domain_item.get("domainEntries")
                            if isinstance(entries, list):
                                for entry in entries:
                                    if not isinstance(entry, dict):
                                        continue
                                    entry_name = entry.get("name")
                                    entry_id = entry.get("id")
                                    if (
                                        isinstance(entry_name, str)
                                        and entry_name == "www"
                                        and isinstance(entry_id, str)
                                        and entry_id.strip()
                                    ):
                                        found_entry_id = entry_id.strip()
                                        break
                            if found_entry_id:
                                break
            if found_domain:
                domain_name = found_domain
                state["domain_name"] = domain_name
            if not found_entry_id and domain_name:
                run_aws_json(
                    aws_bin,
                    endpoint_url,
                    region,
                    "lightsail",
                    "create-domain-entry",
                    env,
                    [
                        "--cli-input-json",
                        json.dumps(
                            {
                                "domainName": domain_name,
                                "domainEntry": {"name": "www", "target": "198.51.100.10", "type": "A"},
                            },
                            separators=(",", ":"),
                        ),
                    ],
                )
                domains_data = run_aws_json(aws_bin, endpoint_url, region, "lightsail", "get-domains", env)
                if isinstance(domains_data, dict):
                    lightsail_record_runtime_payload(region, domains_data)
                    found_entry_id = str(lightsail_runtime_state(region).get("domain_entry_id", found_entry_id))
            if found_entry_id:
                domain_entry_id = found_entry_id
                state["domain_entry_id"] = domain_entry_id

        def _lightsail_wire_keys(value: object) -> object:
            if isinstance(value, dict):
                converted: dict[object, object] = {}
                for key, item in value.items():
                    out_key = key
                    if isinstance(key, str) and key and key[0].isupper():
                        out_key = key[0].lower() + key[1:]
                    converted[out_key] = _lightsail_wire_keys(item)
                return converted
            if isinstance(value, list):
                return [_lightsail_wire_keys(item) for item in value]
            return value

        def _replace_payload(values: dict[str, object]) -> None:
            hydrated.clear()
            converted = _lightsail_wire_keys(values)
            if isinstance(converted, dict):
                hydrated.update(converted)

        # Generic resource references.
        set_key_if_present_case_insensitive(hydrated, "AvailabilityZone", availability_zone)
        set_key_if_present_case_insensitive(hydrated, "BlueprintId", blueprint_id)
        set_key_if_present_case_insensitive(hydrated, "BundleId", bundle_id)
        set_key_if_present_case_insensitive(hydrated, "InstanceName", instance_name)
        set_key_if_present_case_insensitive(hydrated, "InstanceNames", [instance_name])
        set_key_if_present_case_insensitive(hydrated, "SourceInstanceName", instance_name)
        set_key_if_present_case_insensitive(hydrated, "InstanceSnapshotName", instance_snapshot_name)
        set_key_if_present_case_insensitive(hydrated, "DiskName", disk_name)
        set_key_if_present_case_insensitive(hydrated, "DiskSnapshotName", disk_snapshot_name)
        set_key_if_present_case_insensitive(hydrated, "SourceDiskName", disk_name)
        set_key_if_present_case_insensitive(hydrated, "LoadBalancerName", load_balancer_name)
        set_key_if_present_case_insensitive(hydrated, "CertificateName", certificate_name)
        set_key_if_present_case_insensitive(hydrated, "DistributionName", distribution_name)
        set_key_if_present_case_insensitive(hydrated, "DomainName", domain_name)
        set_key_if_present_case_insensitive(hydrated, "BucketName", bucket_name)
        set_key_if_present_case_insensitive(hydrated, "AccessKeyId", bucket_access_key_id)
        set_key_if_present_case_insensitive(hydrated, "ServiceName", container_service_name)
        set_key_if_present_case_insensitive(hydrated, "RelationalDatabaseName", relational_database_name)
        set_key_if_present_case_insensitive(hydrated, "RelationalDatabaseSnapshotName", relational_database_snapshot_name)
        set_key_if_present_case_insensitive(hydrated, "SourceRelationalDatabaseName", relational_database_name)
        set_key_if_present_case_insensitive(hydrated, "StaticIpName", static_ip_name)
        set_key_if_present_case_insensitive(hydrated, "KeyPairName", key_pair_name)
        set_key_if_present_case_insensitive(hydrated, "AlarmName", alarm_name)
        set_key_if_present_case_insensitive(hydrated, "MonitoredResourceName", instance_name)
        set_key_if_present_case_insensitive(hydrated, "ResourceName", instance_name)
        set_key_if_present_case_insensitive(hydrated, "OperationId", operation_id)
        set_key_if_present_case_insensitive(hydrated, "Date", auto_snapshot_date)
        set_key_if_present_case_insensitive(hydrated, "PageToken", "")
        set_key_if_present_case_insensitive(hydrated, "NextPageToken", "")
        set_key_if_present_case_insensitive(hydrated, "NextBackwardToken", "")
