            if op in {"UpdateSecurityGroupRuleDescriptionsIngress", "UpdateSecurityGroupRuleDescriptionsEgress"}:
                is_egress = op.endswith("Egress")
                group_id = ""
                rule_id = ""
                vpc_id = ec2_get_runtime_value("vpcid")
                cidr = "198.51.100.0/24" if is_egress else "203.0.113.0/24"
                from_port = 8443 if is_egress else 8080
                to_port = 8443 if is_egress else 8080
                auth_operation = "authorize-security-group-egress" if is_egress else "authorize-security-group-ingress"

