        second_snapshot_id = (
            str(state.get("second_snapshot_id") or snapshot_id).strip() or snapshot_id
        )
        first_snapshot_id = (
            str(state.get("first_snapshot_id") or snapshot_id).strip() or snapshot_id
        )
        block_index = int(state.get("block_index") or 0)
        block_token = (
            str(state.get("block_token") or f"token-{snapshot_id}-0-seed").strip()
            or f"token-{snapshot_id}-0-seed"
        )

        block_bytes = b"stackyard-ebs-block"
        block_b64 = base64.b64encode(block_bytes).decode("ascii")
        block_checksum = base64.b64encode(hashlib.sha256(block_bytes).digest()).decode("ascii")

        def _set_or_add(key: str, value: object) -> None:
            if not set_key_if_present_case_insensitive(hydrated, key, value):
                hydrated[key] = value

        state["snapshot_id"] = snapshot_id
        state["second_snapshot_id"] = second_snapshot_id
        state["first_snapshot_id"] = first_snapshot_id
        state["block_index"] = block_index
        state["block_token"] = block_token

