def invoke_s3_write_get_object_response_raw(
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    request_route: str,
    request_token: str,
    body_payload: object,
) -> tuple[int, str]:
    base = endpoint_url.rstrip("/")
    url = f"{base}/WriteGetObjectResponse"
    body = s3_decode_body(body_payload)
    extra_headers = {
        "Content-Type": "application/octet-stream",
        "x-amz-request-route": request_route,
        "x-amz-request-token": request_token,
    }
    headers = sigv4_sign(
        method="POST",
        url=url,
        body=body,
        service="s3",
        region=region,
        access_key=env.get("AWS_ACCESS_KEY_ID", ""),
        secret_key=env.get("AWS_SECRET_ACCESS_KEY", ""),
        session_token=env.get("AWS_SESSION_TOKEN", ""),
        extra_headers=extra_headers,
    )
    req = urlrequest.Request(url=url, method="POST", data=body, headers=headers)
    try:
        with urlrequest.urlopen(req, timeout=20.0) as resp:
            text = resp.read().decode("utf-8", errors="replace")
            return int(resp.status), text
    except urlerror.HTTPError as err:
        text = err.read().decode("utf-8", errors="replace")
        return int(err.code), text
    except Exception as err:  # noqa: BLE001
        return 0, str(err)


