def invoke_s3_raw_request_detailed(
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    method: str,
    bucket: str,
    key: str = "",
    query: str = "",
    body: bytes = b"",
    extra_headers: dict[str, str] | None = None,
) -> tuple[int, str, dict[str, str]]:
    base = endpoint_url.rstrip("/")
    path = f"/{urlparse.quote(bucket)}"
    if key:
        path = f"{path}/{urlparse.quote(key, safe='/')}"
    url = f"{base}{path}"
    if query:
        url = f"{url}?{query}"
    headers = sigv4_sign(
        method=method,
        url=url,
        body=body,
        service="s3",
        region=region,
        access_key=env.get("AWS_ACCESS_KEY_ID", ""),
        secret_key=env.get("AWS_SECRET_ACCESS_KEY", ""),
        session_token=env.get("AWS_SESSION_TOKEN", ""),
        extra_headers=extra_headers or {},
    )
    req = urlrequest.Request(
        url=url,
        method=method,
        data=body if body or method in {"POST", "PUT", "PATCH"} else None,
        headers=headers,
    )
    try:
        with urlrequest.urlopen(req, timeout=20.0) as resp:
            text = resp.read().decode("utf-8", errors="replace")
            return int(resp.status), text, {str(k): str(v) for k, v in resp.headers.items()}
    except urlerror.HTTPError as err:
        text = err.read().decode("utf-8", errors="replace")
        return int(err.code), text, {str(k): str(v) for k, v in err.headers.items()}
    except Exception as err:  # noqa: BLE001
        return 0, str(err), {}


def invoke_s3_raw_request(
    endpoint_url: str,
    region: str,
    env: dict[str, str],
    method: str,
    bucket: str,
    key: str = "",
    query: str = "",
    body: bytes = b"",
    extra_headers: dict[str, str] | None = None,
) -> tuple[int, str]:
    status_code, response_text, _ = invoke_s3_raw_request_detailed(
        endpoint_url=endpoint_url,
        region=region,
        env=env,
        method=method,
        bucket=bucket,
        key=key,
        query=query,
        body=body,
        extra_headers=extra_headers,
    )
    return status_code, response_text


